"""
Automation flags for Nova Agent.

This module manages global toggles that control certain automated
behaviours of the system, such as whether posting or content
generation is enabled and whether approval is required before
publishing. Flags are persisted to a JSON file (by default
``config/automation_flags.json``) so that they survive process
restarts. Thread‑safe read and update functions are provided.
"""

from __future__ import annotations

import json
import os
import threading
from pathlib import Path
from typing import Any, Dict

_lock = threading.Lock()

# Location of the flags file. Relative to the project root.
STATE_FILE = Path(os.getenv("AUTOMATION_FLAGS_FILE", "config/automation_flags.json"))

# Default flag values. New flags should be added here with sensible defaults.
DEFAULTS: Dict[str, Any] = {
    "posting_enabled": True,
    "generation_enabled": True,
    "require_approval": False,
}


def _load_state() -> Dict[str, Any]:
    """Read the current automation flags from disk.

    If the state file does not exist or is invalid, a copy of
    ``DEFAULTS`` is returned. Unknown keys are ignored and missing keys
    are filled with default values.
    """
    with _lock:
        try:
            data = json.loads(STATE_FILE.read_text())
        except Exception:
            data = {}
        # Merge defaults
        state: Dict[str, Any] = DEFAULTS.copy()
        for key, value in data.items():
            if key in DEFAULTS:
                state[key] = value
        return state


def _save_state(state: Dict[str, Any]) -> None:
    """Write the given state dictionary to disk.

    Ensures that the parent directory exists before writing.
    """
    with _lock:
        STATE_FILE.parent.mkdir(parents=True, exist_ok=True)
        STATE_FILE.write_text(json.dumps(state, indent=2))


def get_flags() -> Dict[str, Any]:
    """Return a copy of the current automation flags."""
    return _load_state().copy()


def set_flags(**kwargs: Any) -> Dict[str, Any]:
    """Update one or more automation flags.

    Args:
        **kwargs: Keyword arguments mapping flag names to new values.

    Returns:
        The updated state after applying the changes.

    Raises:
        KeyError: If an unknown flag name is provided.
    """
    state = _load_state()
    for key, value in kwargs.items():
        if key not in DEFAULTS:
            raise KeyError(f"Unknown automation flag: {key}")
        state[key] = bool(value) if isinstance(DEFAULTS[key], bool) else value
    _save_state(state)
    return state.copy()


def is_posting_enabled() -> bool:
    """Return True if automated posting is currently enabled."""
    return bool(_load_state()["posting_enabled"])


def set_posting_enabled(value: bool) -> Dict[str, Any]:
    """Set the posting_enabled flag."""
    return set_flags(posting_enabled=value)


def is_generation_enabled() -> bool:
    """Return True if automated content generation is currently enabled."""
    return bool(_load_state()["generation_enabled"])


def set_generation_enabled(value: bool) -> Dict[str, Any]:
    """Set the generation_enabled flag."""
    return set_flags(generation_enabled=value)


def is_approval_required() -> bool:
    """Return True if content approval is required before publishing."""
    return bool(_load_state()["require_approval"])


def set_approval_required(value: bool) -> Dict[str, Any]:
    """Set the require_approval flag."""
    return set_flags(require_approval=value)

"""
Celery application configuration for Nova Agent v7.0

This module sets up Celery with Redis broker for handling scheduled background tasks,
replacing the manual asyncio loops with a robust, scalable scheduler.
"""

import os
from celery import Celery
from celery.schedules import crontab

# Initialize Celery application
celery_app = Celery('nova_agent')

# Broker configuration - use Redis
REDIS_URL = os.getenv('REDIS_URL', 'redis://localhost:6379/0')
celery_app.conf.update(
    broker_url=REDIS_URL,
    result_backend=REDIS_URL,
    timezone='UTC',
    enable_utc=True,
    task_acks_late=True,
    worker_max_tasks_per_child=100,
    task_default_retry_delay=60,  # seconds
    task_max_retries=3,
    broker_connection_retry_on_startup=True,
    # Task routing - all tasks go to 'celery' queue by default
    task_routes={'*': {'queue': 'celery'}},
)

# Beat schedule configuration
celery_app.conf.beat_schedule = {
    # Nightly governance loop - runs at 2:00 AM UTC
    'nightly-governance-loop': {
        'task': 'nova.governance.run_governance_task',
        'schedule': crontab(hour=2, minute=0),
        'args': [],
        'options': {'queue': 'governance'}
    },

    # Hourly memory cleanup
    'hourly-memory-cleanup': {
        'task': 'nova.maintenance.memory_cleanup_task', 
        'schedule': crontab(minute=0),  # Every hour on the hour
        'args': [],
        'options': {'queue': 'maintenance'}
    },

    # Run daily metrics processing at 3am (renamed from daily-analytics-processing)
    'daily-metrics-processing': {
        'task': 'nova.analytics_tasks.process_daily_metrics_task',
        'schedule': crontab(hour=3, minute=0),
        'args': [],
        'options': {'queue': 'analytics'}
    },

    # Weekly competitor analysis - runs Sunday at 4:00 AM UTC
    'weekly-competitor-analysis': {
        'task': 'nova.analysis.competitor_analysis_task',
        'schedule': crontab(hour=4, minute=0, day_of_week=0),  # Sunday
        'args': [],
        'options': {'queue': 'analysis'}
    },

    # Daily trend intelligence scan - runs at 6:00 AM UTC
    'daily-trend-scan': {
        'task': 'nova.trends.daily_trend_scan_task',
        'schedule': crontab(hour=6, minute=0),
        'args': [],
        'options': {'queue': 'trends'}
    },
}

# Task configuration
celery_app.conf.task_annotations = {
    'nova.governance.run_governance_task': {
        'rate_limit': '1/h',  # Max once per hour
        'max_retries': 3,
        'default_retry_delay': 300,  # 5 minutes
    },
    'nova.maintenance.memory_cleanup_task': {
        'rate_limit': '2/h',  # Max twice per hour
        'max_retries': 1,
        'default_retry_delay': 60,
    },
}

# Auto-discover tasks from all nova modules
celery_app.autodiscover_tasks([
    'nova.governance',
    'nova.maintenance', 
    'nova.analytics_tasks',
    'nova.analysis',
    'nova.trends',
])

# Health check task for monitoring
@celery_app.task(name='nova.health_check')
def health_check():
    """Simple health check task for monitoring Celery workers."""
    return {
        'status': 'healthy',
        'worker': True,
        'timestamp': celery_app.now().isoformat()
    }

import logging import random import asyncio log = logging.getLogger("ChaosInjector")
class ChaosConfig: def __init__(self, fail_rate=0.1, delay_ms=500): self.fail_rate = fail_rate self.delay_ms = delay_ms
async def maybe_fail(cfg: ChaosConfig): # Random latency await asyncio.sleep(cfg.delay_ms / 1000.0 * random.random()) if random.random() < cfg.fail_rate: raise RuntimeError("Injected chaos failure")

from __future__ import annotations
import os import sys from typing import Optional from pydantic import BaseModel, Field
FORBIDDEN = {"change-me", "default", "secret", "key", "password"}
class JWTSettings(BaseModel): algorithm: str = Field(default=os.getenv("JWT_ALG", "HS256")) secret_key: Optional[str] = Field(default=os.getenv("JWT_SECRET_KEY")) token_version: int = Field(default=int(os.getenv("JWT_TOKEN_VERSION", "1")))
def validate_keys(self) -> None: if self.algorithm == "HS256": if not self.secret_key: raise ValueError("JWT_SECRET_KEY must be set when JWT_ALG=HS256") if self.secret_key in FORBIDDEN or len(self.secret_key) < 32: raise ValueError("JWT_SECRET_KEY too weak; set a strong 32+ char secret") elif self.algorithm == "RS256": # Not currently supported by the app raise ValueError("RS256 not supported in this build; set JWT_ALG=HS256") else: raise ValueError(f"Unsupported JWT_ALG: {self.algorithm}")
class AppEnv(BaseModel): """Nova application environment variables. These must be set in production.""" jwt: JWTSettings = Field(default_factory=JWTSettings)
# Admin credentials must be provided via environment (no insecure defaults) admin_username: str = Field(default=os.getenv("NOVA_ADMIN_USERNAME", "admin")) admin_password: Optional[str] = Field(default=os.getenv("NOVA_ADMIN_PASSWORD"))
# Required API keys and service URLs openai_api_key: Optional[str] = Field(default=os.getenv("OPENAI_API_KEY")) redis_url: Optional[str] = Field(default=os.getenv("REDIS_URL")) weaviate_url: Optional[str] = Field(default=os.getenv("WEAVIATE_URL"))
# Optional integrations slack_webhook_url: Optional[str] = Field(default=os.getenv("SLACK_WEBHOOK_URL"))
# Email configuration (for alerts) email_sender: Optional[str] = Field(default=os.getenv("EMAIL_SENDER")) email_password: Optional[str] = Field(default=os.getenv("EMAIL_PASSWORD")) email_receiver: Optional[str] = Field(default=os.getenv("EMAIL_RECEIVER"))
def validate_env_or_exit() -> None: """ Validate required environment variables. Exit with a clear error if any are missing or if the JWT keys are invalid. This function should run before app startup. """ try: env = AppEnv() missing_vars = [] insecure_vars = []
# Check for missing critical environment variables if not env.admin_password: missing_vars.append("NOVA_ADMIN_PASSWORD") elif env.admin_password in FORBIDDEN: insecure_vars.append("NOVA_ADMIN_PASSWORD")
if not env.openai_api_key: missing_vars.append("OPENAI_API_KEY") elif env.openai_api_key in FORBIDDEN: insecure_vars.append("OPENAI_API_KEY")
if not env.redis_url: missing_vars.append("REDIS_URL")
if not env.weaviate_url: missing_vars.append("WEAVIATE_URL")
# Check email configuration for secure values if env.email_password and env.email_password in FORBIDDEN: insecure_vars.append("EMAIL_PASSWORD")
# Build error message errors = [] if missing_vars: errors.append(f"Missing required environment variables: {', '.join(missing_vars)}") if insecure_vars: errors.append(f"Insecure values found in: {', '.join(insecure_vars)}")
# Validate JWT settings env.jwt.validate_keys()
# If we have any errors, show them and exit if errors: print("[ENV VALIDATION] Critical configuration errors:", file=sys.stderr) for error in errors: print(f" - {error}", file=sys.stderr) print("\nSet proper environment variables before starting the application.", file=sys.stderr) sys.exit(1)
except Exception as e: print(f"[ENV VALIDATION] {e}", file=sys.stderr) sys.exit(1)

"""
Governance Report Generator

Compiles an enriched governance report including:
- Insight summaries
- Channel recommendations (status + recommendation text)
- New niche suggestions (stubbed; integrate TI subsystem later)
"""

from __future__ import annotations

from datetime import datetime
from typing import List, Dict, Any

try:
    # scoring.py at repository root
    from scoring import METRIC_WEIGHTS  # type: ignore
except Exception:
    METRIC_WEIGHTS = {}


def fetch_trending_niches() -> List[Dict[str, Any]]:
    """
    Stub function to fetch high-potential trending niches.
    Returns a list of dict with keys: 'niche', 'source', 'rpm', 'competition', 'rationale'.
    """
    return [
        {
            "niche": "Electric Vehicles",
            "source": "Google Trends",
            "rpm": 15.0,
            "competition": "low",
            "rationale": (
                "Electric Vehicles are surging in search popularity with high monetization potential "
                "(RPM ~$15) and relatively few established channels."
            ),
        }
    ]


def generate_governance_report(recommendations: List[Dict[str, Any]]) -> Dict[str, Any]:
    """Generate a structured report (as a dict) from channel recommendations and trend data."""
    report: Dict[str, Any] = {}
    report["date"] = datetime.utcnow().strftime("%Y-%m-%d %H:%M:%SZ")

    promote_list = [rec.get("channel") for rec in recommendations if rec.get("status") == "promote"]
    retire_list = [rec.get("channel") for rec in recommendations if rec.get("status") == "retire"]

    insights: List[str] = []
    if promote_list:
        insights.append(
            f"Channels poised for growth: {', '.join(promote_list)} – showing strong momentum and high performance. "
            "Recommend doubling down on these niches."
        )
    if retire_list:
        insights.append(
            f"Underperforming channels: {', '.join(retire_list)} – falling below performance thresholds. "
            "Consider phasing out or pivoting strategy for these."
        )
    if not promote_list and not retire_list:
        insights.append(
            "Most channels are in a stable range with no immediate extreme actions recommended. Continue monitoring for subtle trend shifts."
        )

    # Additional monetization insight (RPM-weight heuristic)
    for rec in recommendations:
        if rec.get("status") == "watch":
            if "Maintain and watch" in str(rec.get("recommendation")) and METRIC_WEIGHTS.get("RPM", 0) > 0:
                insights.append(
                    f"Monetization opportunity: {rec.get('channel')} has high RPM potential. Even with average growth, "
                    "its niche could yield higher revenue – consider modest investment."
                )
                break

    report["insight_summaries"] = insights
    report["channel_recommendations"] = recommendations

    # Add new niche suggestions (stub)
    report["new_niche_suggestions"] = []
    for niche in fetch_trending_niches():
        report["new_niche_suggestions"].append(
            {
                "niche": niche.get("niche"),
                "source": niche.get("source"),
                "rationale": niche.get("rationale"),
            }
        )

    return report

""" Celery tasks for Nova Agent governance operations.
This module contains Celery task definitions for periodic governance operations, replacing the manual scheduling loops with robust, scalable background jobs. """
import asyncio import logging import yaml from typing import Dict, Any, Optional
from nova.celery_app import celery_app
logger = logging.getLogger(__name__)
@celery_app.task( name="nova.governance.run_governance_task", bind=True, autoretry_for=(Exception,), max_retries=3, retry_backoff=True, retry_backoff_max=600, retry_jitter=True ) def run_governance_task(self) -> Dict[str, Any]: """ Celery task to run the nightly governance loop.
This task replaces the manual asyncio loop that was running in FastAPI startup. It handles governance analysis, recommendations, and policy enforcement.
Returns: Dict containing task execution results and metrics """ task_id = self.request.id logger.info(f"Starting governance task {task_id}")
try: # Load governance configuration governance_config = _load_governance_config()
# Import here to avoid circular dependencies from nova.governance.governance_loop import run as governance_run
# Run the governance loop in async context loop = asyncio.new_event_loop() asyncio.set_event_loop(loop)
try: result = loop.run_until_complete( governance_run(governance_config, [], [], []) )
logger.info(f"Governance task {task_id} completed successfully")
# Update metrics _update_governance_metrics(success=True)
return { 'task_id': task_id, 'status': 'completed', 'result': result, 'retry_count': self.request.retries }
finally: loop.close()
except Exception as exc: logger.error(f"Governance task {task_id} failed: {exc}", exc_info=True)
# Update metrics _update_governance_metrics(success=False, error=str(exc))
# Re-raise for Celery retry logic raise
def _load_governance_config() -> Dict[str, Any]: """Load governance configuration from settings file.""" try: with open('config/settings.yaml', 'r') as f: cfg_all = yaml.safe_load(f) return cfg_all.get('governance', {}) except Exception as e: logger.warning(f"Failed to load governance config: {e}") return {}
def _update_governance_metrics(success: bool, error: Optional[str] = None) -> None: """Update Prometheus metrics for governance task execution.""" try: from nova.metrics import ( governance_loop_duration, channels_scored, actions_flagged )
# These would be updated with actual values from the governance run # For now, just log the execution if success: logger.info("Governance metrics updated: success") else: logger.warning(f"Governance metrics updated: failure - {error}")
except ImportError: # Metrics not available, continue silently pass
@celery_app.task( name="nova.governance.run_manual_governance", bind=True ) def run_manual_governance_task(self, config_overrides: Optional[Dict[str, Any]] = None) -> Dict[str, Any]: """ Manually triggered governance task (e.g., from API endpoint).
Args: config_overrides: Optional configuration overrides for this run
Returns: Dict containing task execution results """ task_id = self.request.id logger.info(f"Starting manual governance task {task_id}")
try: # Load base config and apply overrides governance_config = _load_governance_config() if config_overrides: governance_config.update(config_overrides)
# Import here to avoid circular dependencies from nova.governance.governance_loop import run as governance_run
# Run the governance loop loop = asyncio.new_event_loop() asyncio.set_event_loop(loop)
try: result = loop.run_until_complete( governance_run(governance_config, [], [], []) )
logger.info(f"Manual governance task {task_id} completed")
return { 'task_id': task_id, 'status': 'completed', 'result': result, 'config_overrides': config_overrides }
finally: loop.close()
except Exception as exc: logger.error(f"Manual governance task {task_id} failed: {exc}", exc_info=True) raise
@celery_app.task( name="nova.governance.validate_governance_config", bind=True ) def validate_governance_config_task(self) -> Dict[str, Any]: """ Task to validate governance configuration and policies.
This can be run periodically or triggered manually to ensure governance settings are valid and consistent.
Returns: Dict containing validation results """ task_id = self.request.id logger.info(f"Starting governance config validation {task_id}")
try: config = _load_governance_config()
# Validation logic validation_results = { 'config_loaded': bool(config), 'required_keys_present': _validate_required_keys(config), 'metric_weights_valid': _validate_metric_weights(config), 'thresholds_valid': _validate_thresholds(config), }
all_valid = all(validation_results.values())
return { 'task_id': task_id, 'status': 'completed', 'valid': all_valid, 'validation_results': validation_results, 'config': config }
except Exception as exc: logger.error(f"Config validation task {task_id} failed: {exc}", exc_info=True) raise
def _validate_required_keys(config: Dict[str, Any]) -> bool: """Validate that required configuration keys are present.""" required_keys = ['metrics', 'thresholds', 'auto_actions'] return all(key in config for key in required_keys)
def _validate_metric_weights(config: Dict[str, Any]) -> bool: """Validate metric weight configuration.""" try: metrics = config.get('metrics', {}) if not metrics: return False
# Check that weights are numeric and reasonable for weight in metrics.values(): if not isinstance(weight, (int, float)) or weight < 0 or weight > 1: return False
# Check that weights sum to reasonable total (close to 1.0) total_weight = sum(metrics.values()) return 0.8 <= total_weight <= 1.2
except Exception: return False
def _validate_thresholds(config: Dict[str, Any]) -> bool: """Validate threshold configuration.""" try: thresholds = config.get('thresholds', {}) if not thresholds: return False
# Check required thresholds required_thresholds = ['promote', 'retire'] for threshold in required_thresholds: if threshold not in thresholds: return False
value = thresholds[threshold] if not isinstance(value, (int, float)): return False
# Check logical order (promote > retire) if thresholds['promote'] <= thresholds['retire']: return False
return True
except Exception: return False

from dataclasses import dataclass import time import httpx
@dataclass class ToolConfig: name: str ping_url: str expected_ms: int cost_per_call: float
from nova.policy import PolicyEnforcer
class ToolChecker: def __init__(self, cfg): self.enforcer = PolicyEnforcer()
self.cfg = cfg
async def check(self, tool: ToolConfig): self.enforcer.enforce_tool(tool.name) start = time.perf_counter() try: async with httpx.AsyncClient(timeout=5) as c: r = await c.get(tool.ping_url) latency = (time.perf_counter() - start) * 1000 status = 'ok' if r.status_code < 400 else 'error' except Exception: latency = (time.perf_counter() - start) * 1000 status = 'error' score = 50 score += -10 if latency > tool.expected_ms else 5 score += -15 if status=='error' else 0 score += -10 if tool.cost_per_call > self.cfg.get('cost_threshold',0.002) else 0 return {'tool':tool.name,'latency_ms':int(latency),'status':status,'score':score}

""" Governance Scheduler for Nova Agent
This module implements the nightly governance loop that performs: - Niche scoring and evaluation - Tool health checks - Trend scanning and analysis - System optimization recommendations - Performance monitoring and alerts
Runs automatically on a schedule to ensure Nova maintains optimal performance. """
import asyncio import logging import time from datetime import datetime from typing import Dict, Any from pathlib import Path import json import schedule
from utils.memory_manager import store_long, get_relevant_memories from utils.openai_wrapper import chat_completion
logger = logging.getLogger(__name__)
class GovernanceScheduler: """ Scheduler for Nova's governance and self-optimization tasks. """
def __init__(self, config_path: str = "config/governance_config.json"): self.config_path = Path(config_path) self.config = self._load_config() self.last_run = None self.is_running = False
def _load_config(self) -> Dict[str, Any]: """Load governance configuration.""" default_config = { "enabled": True, "schedule": { "niche_scoring": "02:00", # 2 AM "tool_health_check": "03:00", # 3 AM "trend_scanning": "04:00", # 4 AM "performance_analysis": "05:00", # 5 AM "system_optimization": "06:00" # 6 AM }, "retention_days": 30, "alert_thresholds": { "performance_degradation": 0.1, "error_rate": 0.05, "memory_usage": 0.8 } }
if self.config_path.exists(): try: with open(self.config_path, 'r') as f: user_config = json.load(f) default_config.update(user_config) except Exception as e: logger.error(f"Failed to load governance config: {e}")
return default_config
def _save_config(self): """Save governance configuration.""" try: self.config_path.parent.mkdir(parents=True, exist_ok=True) with open(self.config_path, 'w') as f: json.dump(self.config, f, indent=2) except Exception as e: logger.error(f"Failed to save governance config: {e}")
async def run_niche_scoring(self) -> Dict[str, Any]: """Run niche scoring and evaluation.""" try: logger.info("Starting niche scoring cycle")
# Get recent performance data recent_memories = get_relevant_memories("performance", "recent", limit=100)
# Analyze niche performance prompt = f""" Analyze Nova's recent performance across different niches and content types. Based on the following performance data, score each niche and provide recommendations:
Performance Data: {recent_memories[:2000]}
Provide analysis in JSON format with: 1. Niche scores (0-100) 2. Performance trends 3. Optimization recommendations 4. Priority actions """
response = await chat_completion(prompt, temperature=0.3)
try: analysis = json.loads(response) except json.JSONDecodeError: analysis = {"error": "Failed to parse analysis", "raw_response": response}
# Store results store_long("governance", "niche_scoring", json.dumps(analysis))
logger.info("Niche scoring completed") return analysis
except Exception as e: logger.error(f"Niche scoring failed: {e}") return {"error": str(e)}
async def run_tool_health_check(self) -> Dict[str, Any]: """Check health of all integrated tools and APIs.""" try: logger.info("Starting tool health check")
health_status = { "timestamp": datetime.now().isoformat(), "tools": {}, "overall_health": "healthy", "issues": [] }
# Check OpenAI API try: await chat_completion("Health check", temperature=0) health_status["tools"]["openai"] = { "status": "healthy", "response_time": "normal" } except Exception as e: health_status["tools"]["openai"] = { "status": "unhealthy", "error": str(e) } health_status["issues"].append(f"OpenAI API: {str(e)}")
# Check memory systems try: from utils.memory_manager import get_global_memory_manager mm = get_global_memory_manager() memory_status = mm.get_memory_status() health_status["tools"]["memory"] = { "status": "healthy" if memory_status["fully_available"] else "degraded", "details": memory_status } if not memory_status["fully_available"]: health_status["issues"].append("Memory system not fully available") except Exception as e: health_status["tools"]["memory"] = { "status": "unhealthy", "error": str(e) } health_status["issues"].append(f"Memory system: {str(e)}")
# Check external integrations integrations = [ ("notion", "notion_sync"), ("sheets", "sheets_export"), ("metricool", "metricool_post"), ("convertkit", "convertkit_push"), ("gumroad", "gumroad_sync") ]
for name, module in integrations: try: __import__(module) health_status["tools"][name] = {"status": "available"} except ImportError: health_status["tools"][name] = {"status": "not_installed"} except Exception as e: health_status["tools"][name] = {"status": "error", "error": str(e)} health_status["issues"].append(f"{name}: {str(e)}")
# Determine overall health if health_status["issues"]: health_status["overall_health"] = "degraded" if len(health_status["issues"]) < 3 else "unhealthy"
# Store results store_long("governance", "tool_health", json.dumps(health_status))
logger.info(f"Tool health check completed: {health_status['overall_health']}") return health_status
except Exception as e: logger.error(f"Tool health check failed: {e}") return {"error": str(e)}
async def run_trend_scanning(self) -> Dict[str, Any]: """Scan for trends and market changes.""" try: logger.info("Starting trend scanning")
# Get recent content and performance data recent_content = get_relevant_memories("content", "recent", limit=50) recent_performance = get_relevant_memories("performance", "recent", limit=50)
# Analyze trends prompt = f""" Analyze recent content performance and identify emerging trends. Based on the following data, provide trend analysis:
Recent Content: {recent_content[:1500]}
Recent Performance: {recent_performance[:1500]}
Provide analysis in JSON format with: 1. Emerging trends 2. Declining trends 3. Content recommendations 4. Platform opportunities 5. Risk factors """
response = await chat_completion(prompt, temperature=0.4)
try: trends = json.loads(response) except json.JSONDecodeError: trends = {"error": "Failed to parse trends", "raw_response": response}
# Store results store_long("governance", "trend_analysis", json.dumps(trends))
logger.info("Trend scanning completed") return trends
except Exception as e: logger.error(f"Trend scanning failed: {e}") return {"error": str(e)}
async def run_performance_analysis(self) -> Dict[str, Any]: """Analyze system performance and identify optimization opportunities.""" try: logger.info("Starting performance analysis")
# Collect performance metrics metrics = { "response_time": await self._measure_response_time(), "accuracy": await self._measure_accuracy(), "user_satisfaction": await self._measure_user_satisfaction(), "memory_efficiency": await self._measure_memory_efficiency(), "error_rate": await self._measure_error_rate(), "throughput": await self._measure_throughput() }
# Analyze performance trends recent_metrics = get_relevant_memories("metrics", "recent", limit=20)
prompt = f""" Analyze Nova's performance metrics and identify optimization opportunities.
Current Metrics: {json.dumps(metrics, indent=2)}
Recent Metrics History: {recent_metrics[:1000]}
Provide analysis in JSON format with: 1. Performance trends 2. Bottlenecks identified 3. Optimization recommendations 4. Priority improvements 5. Risk assessments """
response = await chat_completion(prompt, temperature=0.3)
try: analysis = json.loads(response) analysis["current_metrics"] = metrics except json.JSONDecodeError: analysis = { "error": "Failed to parse analysis", "raw_response": response, "current_metrics": metrics }
# Store results store_long("governance", "performance_analysis", json.dumps(analysis))
logger.info("Performance analysis completed") return analysis
except Exception as e: logger.error(f"Performance analysis failed: {e}") return {"error": str(e)}
async def run_system_optimization(self) -> Dict[str, Any]: """Generate system optimization recommendations.""" try: logger.info("Starting system optimization")
# Get recent governance data niche_data = get_relevant_memories("governance", "niche_scoring", limit=5) health_data = get_relevant_memories("governance", "tool_health", limit=5) trend_data = get_relevant_memories("governance", "trend_analysis", limit=5) performance_data = get_relevant_memories("governance", "performance_analysis", limit=5)
# Generate optimization recommendations prompt = f""" Based on recent governance data, generate system optimization recommendations.
Niche Scoring: {niche_data[:1000]}
Tool Health: {health_data[:1000]}
Trend Analysis: {trend_data[:1000]}
Performance Analysis: {performance_data[:1000]}
Provide comprehensive optimization plan in JSON format with: 1. Immediate actions (next 24 hours) 2. Short-term improvements (next week) 3. Long-term optimizations (next month) 4. Resource allocation recommendations 5. Risk mitigation strategies 6. Success metrics """
response = await chat_completion(prompt, temperature=0.3)
try: optimization = json.loads(response) except json.JSONDecodeError: optimization = {"error": "Failed to parse optimization", "raw_response": response}
# Store results store_long("governance", "optimization_plan", json.dumps(optimization))
logger.info("System optimization completed") return optimization
except Exception as e: logger.error(f"System optimization failed: {e}") return {"error": str(e)}
async def _measure_response_time(self) -> float: """Measure average response time.""" # Simulate measurement return 0.65
async def _measure_accuracy(self) -> float: """Measure intent classification accuracy.""" # Simulate measurement return 0.85
async def _measure_user_satisfaction(self) -> float: """Measure user satisfaction score.""" # Simulate measurement return 0.78
async def _measure_memory_efficiency(self) -> float: """Measure memory usage efficiency.""" # Simulate measurement return 0.92
async def _measure_error_rate(self) -> float: """Measure error rate.""" # Simulate measurement return 0.12
async def _measure_throughput(self) -> float: """Measure requests per second throughput.""" # Simulate measurement return 0.88
async def run_full_governance_cycle(self) -> Dict[str, Any]: """Run the complete governance cycle.""" if self.is_running: logger.warning("Governance cycle already running") return {"error": "Already running"}
self.is_running = True start_time = time.time()
try: logger.info("Starting full governance cycle")
results = { "cycle_start": datetime.now().isoformat(), "tasks": {} }
# Run all governance tasks tasks = [ ("niche_scoring", self.run_niche_scoring), ("tool_health_check", self.run_tool_health_check), ("trend_scanning", self.run_trend_scanning), ("performance_analysis", self.run_performance_analysis), ("system_optimization", self.run_system_optimization) ]
for task_name, task_func in tasks: try: logger.info(f"Running {task_name}") task_result = await task_func() results["tasks"][task_name] = { "status": "completed", "result": task_result } except Exception as e: logger.error(f"Task {task_name} failed: {e}") results["tasks"][task_name] = { "status": "failed", "error": str(e) }
results["cycle_duration"] = time.time() - start_time results["cycle_end"] = datetime.now().isoformat()
# Store cycle results store_long("governance", "cycle_results", json.dumps(results))
self.last_run = datetime.now() logger.info(f"Governance cycle completed in {results['cycle_duration']:.2f}s")
return results
except Exception as e: logger.error(f"Governance cycle failed: {e}") return {"error": str(e)} finally: self.is_running = False
def schedule_governance_tasks(self): """Schedule governance tasks.""" if not self.config.get("enabled", True): logger.info("Governance scheduler disabled") return
schedule_config = self.config.get("schedule", {})
# Schedule individual tasks for task_name, time_str in schedule_config.items(): schedule.every().day.at(time_str).do( lambda t=task_name: asyncio.create_task(self._run_scheduled_task(t)) ) logger.info(f"Scheduled {task_name} at {time_str}")
# Schedule full cycle as backup schedule.every().day.at("01:00").do( lambda: asyncio.create_task(self.run_full_governance_cycle()) ) logger.info("Scheduled full governance cycle at 01:00")
async def _run_scheduled_task(self, task_name: str): """Run a scheduled governance task.""" try: if task_name == "niche_scoring": await self.run_niche_scoring() elif task_name == "tool_health_check": await self.run_tool_health_check() elif task_name == "trend_scanning": await self.run_trend_scanning() elif task_name == "performance_analysis": await self.run_performance_analysis() elif task_name == "system_optimization": await self.run_system_optimization() except Exception as e: logger.error(f"Scheduled task {task_name} failed: {e}")
def run_scheduler(self): """Run the scheduler loop.""" logger.info("Starting governance scheduler") self.schedule_governance_tasks()
while True: try: schedule.run_pending() time.sleep(60) # Check every minute except KeyboardInterrupt: logger.info("Governance scheduler stopped") break except Exception as e: logger.error(f"Scheduler error: {e}") time.sleep(60)
# Global scheduler instance governance_scheduler = GovernanceScheduler()
async def run_governance_cycle(): """Convenience function to run governance cycle.""" return await governance_scheduler.run_full_governance_cycle()
def start_governance_scheduler(): """Start the governance scheduler.""" governance_scheduler.run_scheduler()

"""
Celery tasks for Nova Agent maintenance operations.

This module contains background maintenance tasks like memory cleanup,
log rotation, and system health checks.
"""

import asyncio
import logging
import os
import yaml
from datetime import datetime, timedelta
from typing import Dict, Any, Optional

from nova.celery_app import celery_app

logger = logging.getLogger(__name__)

@celery_app.task(
    name="nova.maintenance.memory_cleanup_task",
    bind=True,
    autoretry_for=(Exception,),
    max_retries=1,
    retry_backoff=True
)
def memory_cleanup_task(self, max_age_hours: int = 24) -> Dict[str, Any]:
    """
    Celery task to perform memory and cache cleanup.

    This task replaces the hourly memory cleanup that was running
    in the manual FastAPI startup loop.

    Args:
        max_age_hours: Maximum age of items to keep in hours

    Returns:
        Dict containing cleanup results and metrics
    """
    task_id = self.request.id
    logger.info(f"Starting memory cleanup task {task_id}")

    try:
        # Load memory limit from policy if available
        memory_limit_mb = _load_memory_limit()

        # Import here to avoid circular dependencies
        from nova.memory_guard import cleanup as memory_cleanup

        # Run the cleanup in async context
        loop = asyncio.new_event_loop()
        asyncio.set_event_loop(loop)

        try:
            result = loop.run_until_complete(
                memory_cleanup(
                    max_age_hours=max_age_hours,
                    memory_limit_mb=memory_limit_mb
                )
            )

            logger.info(f"Memory cleanup task {task_id} completed")

            return {
                'task_id': task_id,
                'status': 'completed',
                'cleaned_items': result.get('cleaned_items', 0) if result else 0,
                'memory_freed_mb': result.get('memory_freed_mb', 0) if result else 0,
                'max_age_hours': max_age_hours,
                'memory_limit_mb': memory_limit_mb
            }

        finally:
            loop.close()

    except Exception as exc:
        logger.error(f"Memory cleanup task {task_id} failed: {exc}", exc_info=True)
        # Don't retry extensively for cleanup tasks
        if self.request.retries >= 1:
            logger.warning("Memory cleanup failed after retries, continuing")
            return {
                'task_id': task_id,
                'status': 'failed',
                'error': str(exc),
                'retries': self.request.retries
            }
        raise


@celery_app.task(
    name="nova.maintenance.log_rotation_task",
    bind=True
)
def log_rotation_task(self, max_log_age_days: int = 7) -> Dict[str, Any]:
    """
    Task to rotate and clean up old log files.

    Args:
        max_log_age_days: Maximum age of log files to keep

    Returns:
        Dict containing rotation results
    """
    task_id = self.request.id
    logger.info(f"Starting log rotation task {task_id}")

    try:
        logs_dir = "logs"
        if not os.path.exists(logs_dir):
            return {
                'task_id': task_id,
                'status': 'skipped',
                'reason': 'logs directory not found'
            }

        cutoff_date = datetime.now() - timedelta(days=max_log_age_days)
        files_removed = 0
        bytes_freed = 0

        for filename in os.listdir(logs_dir):
            if not filename.endswith('.log'):
                continue

            filepath = os.path.join(logs_dir, filename)

            try:
                # Check file age
                file_time = datetime.fromtimestamp(os.path.getmtime(filepath))
                if file_time < cutoff_date:
                    file_size = os.path.getsize(filepath)
                    os.remove(filepath)
                    files_removed += 1
                    bytes_freed += file_size
                    logger.debug(f"Removed old log file: {filename}")

            except OSError as e:
                logger.warning(f"Failed to remove log file {filename}: {e}")

        logger.info(f"Log rotation completed: {files_removed} files removed, {bytes_freed} bytes freed")

        return {
            'task_id': task_id,
            'status': 'completed',
            'files_removed': files_removed,
            'bytes_freed': bytes_freed,
            'max_age_days': max_log_age_days
        }

    except Exception as exc:
        logger.error(f"Log rotation task {task_id} failed: {exc}", exc_info=True)
        raise


@celery_app.task(
    name="nova.maintenance.system_health_check",
    bind=True
)
def system_health_check_task(self) -> Dict[str, Any]:
    """
    Comprehensive system health check task.

    Checks various system components and reports health status.

    Returns:
        Dict containing health check results
    """
    task_id = self.request.id
    logger.info(f"Starting system health check {task_id}")

    try:
        health_results = {
            'disk_space': _check_disk_space(),
            'memory_usage': _check_memory_usage(),
            'database_connection': _check_database_connection(),
            'redis_connection': _check_redis_connection(),
            'config_files': _check_config_files(),
        }

        # Calculate overall health
        healthy_checks = sum(1 for result in health_results.values() if result.get('healthy', False))
        total_checks = len(health_results)
        overall_healthy = healthy_checks == total_checks

        result = {
            'task_id': task_id,
            'status': 'completed',
            'overall_healthy': overall_healthy,
            'healthy_checks': healthy_checks,
            'total_checks': total_checks,
            'checks': health_results,
            'timestamp': datetime.utcnow().isoformat()
        }

        if not overall_healthy:
            logger.warning(f"System health check found issues: {healthy_checks}/{total_checks} checks passed")
        else:
            logger.info("System health check: all systems healthy")

        return result

    except Exception as exc:
        logger.error(f"System health check {task_id} failed: {exc}", exc_info=True)
        raise


def _load_memory_limit() -> Optional[int]:
    """Load memory limit from policy configuration."""
    try:
        with open('config/policy.yaml', 'r') as f:
            policy_cfg = yaml.safe_load(f)
        return policy_cfg.get('sandbox', {}).get('memory_limit_mb')
    except Exception:
        return None


def _check_disk_space() -> Dict[str, Any]:
    """Check available disk space."""
    try:
        import shutil
        total, used, free = shutil.disk_usage('.')

        free_percent = (free / total) * 100
        healthy = free_percent > 10  # Alert if less than 10% free

        return {
            'healthy': healthy,
            'free_bytes': free,
            'total_bytes': total,
            'free_percent': free_percent
        }
    except Exception as e:
        return {'healthy': False, 'error': str(e)}


def _check_memory_usage() -> Dict[str, Any]:
    """Check system memory usage."""
    try:
        import psutil
        memory = psutil.virtual_memory()

        healthy = memory.percent < 90  # Alert if more than 90% used

        return {
            'healthy': healthy,
            'used_percent': memory.percent,
            'available_bytes': memory.available,
            'total_bytes': memory.total
        }
    except ImportError:
        return {'healthy': True, 'error': 'psutil not available'}
    except Exception as e:
        return {'healthy': False, 'error': str(e)}


def _check_database_connection() -> Dict[str, Any]:
    """Check database connectivity."""
    try:
        # This would depend on your database setup
        # For now, just check if the database module can be imported
        from nova.db import get_db
        return {'healthy': True, 'status': 'connected'}
    except ImportError:
        return {'healthy': True, 'status': 'no_database_module'}
    except Exception as e:
        return {'healthy': False, 'error': str(e)}


def _check_redis_connection() -> Dict[str, Any]:
    """Check Redis connectivity."""
    try:
        import redis
        redis_url = os.getenv('REDIS_URL', 'redis://localhost:6379/0')
        r = redis.from_url(redis_url)
        r.ping()
        return {'healthy': True, 'status': 'connected'}
    except Exception as e:
        return {'healthy': False, 'error': str(e)}


def _check_config_files() -> Dict[str, Any]:
    """Check that required configuration files exist and are valid."""
    try:
        config_files = [
            'config/settings.yaml',
            'governance_config.yaml',
        ]

        results = {}
        all_healthy = True

        for config_file in config_files:
            try:
                with open(config_file, 'r') as f:
                    yaml.safe_load(f)
                results[config_file] = {'exists': True, 'valid': True}
            except FileNotFoundError:
                results[config_file] = {'exists': False, 'valid': False}
                all_healthy = False
            except yaml.YAMLError:
                results[config_file] = {'exists': True, 'valid': False}
                all_healthy = False

        return {
            'healthy': all_healthy,
            'files': results
        }
    except Exception as e:
        return {'healthy': False, 'error': str(e)}

""" Context Management System for Nova Agent NLP
This module manages conversation context, user history, and system state to provide better intent classification and response generation. """
import json import time from typing import Dict, List, Any, Optional from dataclasses import dataclass, asdict from datetime import datetime from collections import deque import logging
logger = logging.getLogger(__name__)
@dataclass class ConversationTurn: """Represents a single turn in the conversation""" timestamp: float user_message: str system_response: str intent: str confidence: float entities: Dict[str, Any] context_snapshot: Dict[str, Any]
@dataclass class SystemState: """Current system state for context awareness""" loop_active: bool current_avatar: str last_rpm_check: float last_content_created: float active_platforms: List[str] current_task: Optional[str] error_count: int performance_metrics: Dict[str, float]
class ContextManager: """Manages conversation context and system state"""
def __init__(self, max_history: int = 50): self.max_history = max_history self.conversation_history = deque(maxlen=max_history) self.system_state = SystemState( loop_active=False, current_avatar="default", last_rpm_check=0.0, last_content_created=0.0, active_platforms=[], current_task=None, error_count=0, performance_metrics={} ) self.user_preferences = {} self.session_start = time.time()
def add_conversation_turn(self, turn: ConversationTurn): """Add a new conversation turn to history""" self.conversation_history.append(turn) logger.info(f"Added conversation turn: {turn.intent} (confidence: {turn.confidence})")
def get_recent_context(self, turns: int = 5) -> List[ConversationTurn]: """Get the most recent conversation turns""" return list(self.conversation_history)[-turns:]
def get_context_for_intent(self, message: str) -> Dict[str, Any]: """Get relevant context for intent classification""" context = { "system_state": asdict(self.system_state), "recent_intents": self._get_recent_intents(), "user_preferences": self.user_preferences, "session_duration": time.time() - self.session_start, "conversation_length": len(self.conversation_history) }
# Add conversation history if relevant if self.conversation_history: recent_turns = self.get_recent_context(3) context["recent_conversation"] = [ { "user": turn.user_message, "intent": turn.intent, "timestamp": turn.timestamp } for turn in recent_turns ]
# Add time-based context context["time_context"] = self._get_time_context()
return context
def update_system_state(self, **kwargs): """Update system state with new information""" for key, value in kwargs.items(): if hasattr(self.system_state, key): setattr(self.system_state, key, value) logger.info(f"Updated system state: {key} = {value}")
def get_system_state(self) -> SystemState: """Get current system state""" return self.system_state
def _get_recent_intents(self) -> List[str]: """Get list of recent intents for context""" recent_turns = self.get_recent_context(10) return [turn.intent for turn in recent_turns]
def _get_time_context(self) -> Dict[str, Any]: """Get time-based context information""" now = datetime.now() return { "hour": now.hour, "day_of_week": now.weekday(), "is_business_hours": 9 <= now.hour <= 17, "time_since_last_rpm": time.time() - self.system_state.last_rpm_check, "time_since_last_content": time.time() - self.system_state.last_content_created }
def get_user_preferences(self) -> Dict[str, Any]: """Get user preferences for context""" return self.user_preferences.copy()
def update_user_preferences(self, preferences: Dict[str, Any]): """Update user preferences""" self.user_preferences.update(preferences) logger.info(f"Updated user preferences: {preferences}")
def save_context(self, filepath: str): """Save context to file for persistence""" try: context_data = { "conversation_history": [asdict(turn) for turn in self.conversation_history], "system_state": asdict(self.system_state), "user_preferences": self.user_preferences, "session_start": self.session_start }
with open(filepath, 'w') as f: json.dump(context_data, f, indent=2, default=str)
logger.info(f"Context saved to {filepath}") except Exception as e: logger.error(f"Failed to save context: {e}")
def load_context(self, filepath: str): """Load context from file""" try: with open(filepath, 'r') as f: context_data = json.load(f)
# Restore conversation history self.conversation_history.clear() for turn_data in context_data.get("conversation_history", []): turn = ConversationTurn(**turn_data) self.conversation_history.append(turn)
# Restore system state state_data = context_data.get("system_state", {}) self.system_state = SystemState(**state_data)
# Restore user preferences self.user_preferences = context_data.get("user_preferences", {})
# Restore session start self.session_start = context_data.get("session_start", time.time())
logger.info(f"Context loaded from {filepath}") except Exception as e: logger.error(f"Failed to load context: {e}")
# Global context manager instance context_manager = ContextManager()
def get_context_for_intent(message: str) -> Dict[str, Any]: """Convenience function to get context for intent classification""" return context_manager.get_context_for_intent(message)
def update_system_state(**kwargs): """Convenience function to update system state""" context_manager.update_system_state(**kwargs)

""" Advanced NLP Intent Classification System for Nova Agent
This module provides sophisticated intent detection using multiple approaches: 1. Rule-based classification with regex patterns 2. Semantic similarity using embeddings 3. Machine learning classification with OpenAI 4. Context-aware intent resolution 5. Confidence scoring and fallback handling """
import re import json import logging from typing import Dict, List, Any from dataclasses import dataclass from enum import Enum import numpy as np from sentence_transformers import SentenceTransformer from utils.openai_wrapper import chat_completion from utils.model_router import get_model_for_task
# Configure logging logging.basicConfig(level=logging.INFO) logger = logging.getLogger(__name__)
class IntentType(Enum): """Enumeration of all possible intents in the Nova system""" # System Control Intents RESUME_LOOP = "resume_loop" PAUSE_LOOP = "pause_loop" STOP_LOOP = "stop_loop" STATUS_CHECK = "status_check"
# Analytics & Reporting Intents GET_RPM = "get_rpm" GET_ANALYTICS = "get_analytics" GET_PERFORMANCE = "get_performance" GET_REPORTS = "get_reports"
# Content Management Intents CREATE_CONTENT = "create_content" EDIT_CONTENT = "edit_content" DELETE_CONTENT = "delete_content" SCHEDULE_CONTENT = "schedule_content"
# Avatar Management Intents SWITCH_AVATAR = "switch_avatar" CONFIGURE_AVATAR = "configure_avatar" AVATAR_PERFORMANCE = "avatar_performance"
# Platform Management Intents PLATFORM_STATUS = "platform_status" CONNECT_PLATFORM = "connect_platform" DISCONNECT_PLATFORM = "disconnect_platform"
# Memory & Learning Intents QUERY_MEMORY = "query_memory" LEARN_FROM_DATA = "learn_from_data" OPTIMIZE_PROMPTS = "optimize_prompts"
# Configuration Intents UPDATE_CONFIG = "update_config" GET_CONFIG = "get_config" RESET_CONFIG = "reset_config"
# Emergency & Debug Intents EMERGENCY_STOP = "emergency_stop" DEBUG_MODE = "debug_mode" SYSTEM_HEALTH = "system_health"
# Generic Intents CHAT = "chat" HELP = "help" UNKNOWN = "unknown"
@dataclass class IntentResult: """Structured result from intent classification""" intent: IntentType confidence: float entities: Dict[str, Any] context: Dict[str, Any] raw_message: str classification_method: str
class IntentClassifier: """Advanced intent classification system"""
def __init__(self): self.embedder = SentenceTransformer('all-MiniLM-L6-v2') self.intent_patterns = self._load_intent_patterns() self.intent_examples = self._load_intent_examples() self.confidence_threshold = 0.7
def _load_intent_patterns(self) -> Dict[IntentType, List[str]]: """Load regex patterns for each intent type""" return { IntentType.RESUME_LOOP: [ r'\b(resume|start|begin|continue|restart)\b', r'\b(turn on|activate|enable)\b.*\b(loop|system|nova)\b', r'\b(get|make)\b.*\b(going|running)\b' ], IntentType.PAUSE_LOOP: [ r'\b(pause|stop|halt|suspend)\b', r'\b(turn off|deactivate|disable)\b.*\b(loop|system)\b', r'\b(put|set)\b.*\b(on hold|standby)\b' ], IntentType.GET_RPM: [ r'\b(rpm|revenue|earnings|money|income)\b', r'\b(how much|what is|show me)\b.*\b(making|earning)\b', r'\b(performance|metrics|stats)\b.*\b(revenue|money)\b' ], IntentType.GET_ANALYTICS: [ r'\b(analytics|data|insights|metrics|stats)\b', r'\b(how are|what are)\b.*\b(performing|doing)\b', r'\b(show|get|display)\b.*\b(performance|results)\b' ], IntentType.CREATE_CONTENT: [ r'\b(create|make|generate|produce)\b.*\b(content|video|post)\b', r'\b(new|fresh)\b.*\b(content|video|post)\b', r'\b(write|script|film)\b.*\b(video|content)\b' ], IntentType.SWITCH_AVATAR: [ r'\b(switch|change|swap)\b.*\b(avatar|character|persona)\b', r'\b(use|activate)\b.*\b(avatar|character)\b', r'\b(different|new)\b.*\b(avatar|character)\b' ], IntentType.QUERY_MEMORY: [ r'\b(remember|recall|memory|history)\b', r'\b(what did|when did|how did)\b.*\b(before|previously)\b', r'\b(show|get)\b.*\b(history|past|memory)\b' ], IntentType.HELP: [ r'\b(help|assist|support)\b', r'\b(what can|how do|how to)\b', r'\b(guide|tutorial|instructions)\b' ] }
def _load_intent_examples(self) -> Dict[IntentType, List[str]]: """Load example phrases for each intent for semantic matching""" return { IntentType.RESUME_LOOP: [ "resume the system", "start nova loop", "continue operations", "turn on the automation", "get the system running", "activate nova agent" ], IntentType.GET_RPM: [ "what's our current RPM", "show me the revenue", "how much money are we making", "what are our earnings", "display RPM metrics", "current revenue performance" ], IntentType.CREATE_CONTENT: [ "create a new video", "generate content", "make a post", "write a script", "produce a video", "create fresh content" ], IntentType.SWITCH_AVATAR: [ "switch to a different avatar", "change the character", "use a new persona", "activate different avatar", "swap the character", "different avatar please" ], IntentType.QUERY_MEMORY: [ "what did we do before", "show me the history", "recall previous actions", "what's in memory", "show past operations", "get historical data" ] }
def classify_intent(self, message: str, context: Dict[str, Any] = None) -> IntentResult: """ Main intent classification method using multiple approaches
Args: message: User input message context: Additional context (user history, system state, etc.)
Returns: IntentResult with classified intent and metadata """ context = context or {}
# Method 1: Rule-based classification rule_result = self._rule_based_classification(message, context) if rule_result.confidence > self.confidence_threshold: return rule_result
# Method 2: Semantic similarity semantic_result = self._semantic_classification(message, context) if semantic_result.confidence > self.confidence_threshold: return semantic_result
# Method 3: AI-powered classification ai_result = self._ai_classification(message, context) if ai_result.confidence > self.confidence_threshold: return ai_result
# Fallback to generic chat return IntentResult( intent=IntentType.CHAT, confidence=0.5, entities={}, context=context, raw_message=message, classification_method="fallback" )
def _rule_based_classification(self, message: str, context: Dict[str, Any] = None) -> IntentResult: """Rule-based classification using regex patterns""" context = context or {} message_lower = message.lower()
for intent_type, patterns in self.intent_patterns.items(): for pattern in patterns: if re.search(pattern, message_lower, re.IGNORECASE): # Extract entities from the match entities = self._extract_entities(message, pattern)
return IntentResult( intent=intent_type, confidence=0.85, # High confidence for exact matches entities=entities, context=context, raw_message=message, classification_method="rule_based" )
return IntentResult( intent=IntentType.UNKNOWN, confidence=0.0, entities={}, context=context, raw_message=message, classification_method="rule_based" )
def _semantic_classification(self, message: str, context: Dict[str, Any] = None) -> IntentResult: """Semantic classification using sentence embeddings""" context = context or {} try: message_embedding = self.embedder.encode([message])[0]
best_intent = IntentType.UNKNOWN best_similarity = 0.0
for intent_type, examples in self.intent_examples.items(): if not examples: continue
# Encode all examples for this intent example_embeddings = self.embedder.encode(examples)
# Calculate similarity with each example similarities = [] for example_emb in example_embeddings: similarity = np.dot(message_embedding, example_emb) / ( np.linalg.norm(message_embedding) * np.linalg.norm(example_emb) ) similarities.append(similarity)
# Get max similarity for this intent max_similarity = max(similarities) if max_similarity > best_similarity: best_similarity = max_similarity best_intent = intent_type
return IntentResult( intent=best_intent, confidence=best_similarity, entities={}, context=context, raw_message=message, classification_method="semantic" )
except Exception as e: logger.error(f"Semantic classification failed: {e}") return IntentResult( intent=IntentType.UNKNOWN, confidence=0.0, entities={}, context={}, raw_message=message, classification_method="semantic_error" )
def _ai_classification(self, message: str, context: Dict[str, Any]) -> IntentResult: """AI-powered classification using OpenAI""" try: # Prepare context for AI context_str = "" if context: context_str = f"\nContext: {json.dumps(context, indent=2)}"
# Create classification prompt prompt = f"""Classify the user's intent from the following message. Choose from these intent types:
{chr(10).join([f"- {intent.value}: {self._get_intent_description(intent)}" for intent in IntentType])}
Message: "{message}"{context_str}
Respond with JSON only: {{ "intent": "intent_type_value", "confidence": 0.0-1.0, "entities": {{"key": "value"}}, "reasoning": "brief explanation" }}"""
# Get AI classification model = get_model_for_task("intent_classification") response = chat_completion(prompt, model=model, temperature=0.1)
# Parse response try: result = json.loads(response) intent_type = IntentType(result.get("intent", "unknown")) confidence = float(result.get("confidence", 0.5)) entities = result.get("entities", {})
return IntentResult( intent=intent_type, confidence=confidence, entities=entities, context=context, raw_message=message, classification_method="ai_powered" ) except (json.JSONDecodeError, ValueError) as e: logger.error(f"Failed to parse AI classification response: {e}") return IntentResult( intent=IntentType.UNKNOWN, confidence=0.0, entities={}, context=context, raw_message=message, classification_method="ai_parse_error" )
except Exception as e: logger.error(f"AI classification failed: {e}") return IntentResult( intent=IntentType.UNKNOWN, confidence=0.0, entities={}, context=context, raw_message=message, classification_method="ai_error" )
def _extract_entities(self, message: str, pattern: str) -> Dict[str, Any]: """Extract named entities from message using regex patterns""" entities = {}
# Extract platform mentions platform_patterns = { 'tiktok': r'\b(tiktok|tiktok)\b', 'instagram': r'\b(instagram|ig)\b', 'youtube': r'\b(youtube|yt)\b', 'facebook': r'\b(facebook|fb)\b' }
for platform, platform_pattern in platform_patterns.items(): if re.search(platform_pattern, message.lower()): entities['platform'] = platform
# Extract numbers (for RPM, counts, etc.) number_match = re.search(r'\b(\d+(?:\.\d+)?)\b', message) if number_match: entities['number'] = float(number_match.group(1))
# Extract time references time_patterns = { 'today': r'\b(today|now)\b', 'yesterday': r'\b(yesterday)\b', 'this_week': r'\b(this week|current week)\b', 'this_month': r'\b(this month|current month)\b' }
for time_ref, time_pattern in time_patterns.items(): if re.search(time_pattern, message.lower()): entities['time_reference'] = time_ref
return entities
def _get_intent_description(self, intent: IntentType) -> str: """Get human-readable description for each intent""" descriptions = { IntentType.RESUME_LOOP: "Resume or start the Nova automation loop", IntentType.PAUSE_LOOP: "Pause or stop the Nova automation loop", IntentType.GET_RPM: "Get current revenue per mille metrics", IntentType.GET_ANALYTICS: "Get performance analytics and insights", IntentType.CREATE_CONTENT: "Create new video content or posts", IntentType.SWITCH_AVATAR: "Switch to a different avatar/character", IntentType.QUERY_MEMORY: "Query system memory or history", IntentType.HELP: "Get help or assistance", IntentType.CHAT: "General conversation or chat", IntentType.UNKNOWN: "Unknown or unclear intent" } return descriptions.get(intent, "No description available")
# Global classifier instance intent_classifier = IntentClassifier()
def classify_intent(message: str, context: Dict[str, Any] = None) -> IntentResult: """Convenience function to classify intent""" return intent_classifier.classify_intent(message, context)

"""
Training Data Management for Nova Agent NLP

This module manages training data collection, validation, and improvement
for the intent classification system.
"""

import json
import logging
from typing import Dict, List, Any, Optional
from dataclasses import dataclass, asdict
from datetime import datetime
from pathlib import Path

logger = logging.getLogger(__name__)

@dataclass
class TrainingExample:
    """Represents a training example for intent classification"""
    message: str
    intent: str
    confidence: float
    entities: Dict[str, Any]
    context: Dict[str, Any]
    timestamp: float
    user_feedback: Optional[str] = None
    corrected_intent: Optional[str] = None
    source: str = "user_input"

@dataclass
class IntentTrainingData:
    """Training data for a specific intent"""
    intent: str
    examples: List[TrainingExample]
    patterns: List[str]
    synonyms: List[str]
    common_entities: List[str]

class TrainingDataManager:
    """Manages training data for NLP improvement"""

    def __init__(self, data_dir: str = "data/nlp_training"):
        self.data_dir = Path(data_dir)
        self.data_dir.mkdir(parents=True, exist_ok=True)
        self.examples_file = self.data_dir / "training_examples.json"
        self.intents_file = self.data_dir / "intent_data.json"
        self.feedback_file = self.data_dir / "user_feedback.json"

        # Load existing data
        self.training_examples = self._load_training_examples()
        self.intent_data = self._load_intent_data()
        self.user_feedback = self._load_user_feedback()

    def add_training_example(self, example: TrainingExample):
        """Add a new training example"""
        self.training_examples.append(example)
        self._save_training_examples()
        logger.info(f"Added training example for intent: {example.intent}")

    def add_user_feedback(self, original_intent: str, corrected_intent: str, 
                         message: str, feedback: str):
        """Add user feedback for intent correction"""
        feedback_entry = {
            "timestamp": datetime.now().isoformat(),
            "original_intent": original_intent,
            "corrected_intent": corrected_intent,
            "message": message,
            "feedback": feedback
        }

        self.user_feedback.append(feedback_entry)
        self._save_user_feedback()
        logger.info(f"Added user feedback: {original_intent} -> {corrected_intent}")

    def get_training_examples(self, intent: Optional[str] = None) -> List[TrainingExample]:
        """Get training examples, optionally filtered by intent"""
        if intent:
            return [ex for ex in self.training_examples if ex.intent == intent]
        return self.training_examples.copy()

    def get_intent_data(self, intent: str) -> Optional[IntentTrainingData]:
        """Get training data for a specific intent"""
        return self.intent_data.get(intent)

    def update_intent_patterns(self, intent: str, patterns: List[str]):
        """Update regex patterns for an intent"""
        if intent not in self.intent_data:
            self.intent_data[intent] = IntentTrainingData(
                intent=intent,
                examples=[],
                patterns=patterns,
                synonyms=[],
                common_entities=[]
            )
        else:
            self.intent_data[intent].patterns = patterns

        self._save_intent_data()
        logger.info(f"Updated patterns for intent: {intent}")

    def add_intent_synonyms(self, intent: str, synonyms: List[str]):
        """Add synonyms for an intent"""
        if intent not in self.intent_data:
            self.intent_data[intent] = IntentTrainingData(
                intent=intent,
                examples=[],
                patterns=[],
                synonyms=synonyms,
                common_entities=[]
            )
        else:
            self.intent_data[intent].synonyms.extend(synonyms)

        self._save_intent_data()
        logger.info(f"Added synonyms for intent: {intent}")

    def generate_training_report(self) -> Dict[str, Any]:
        """Generate a report on training data quality"""
        report = {
            "total_examples": len(self.training_examples),
            "intents_covered": len(set(ex.intent for ex in self.training_examples)),
            "examples_per_intent": {},
            "feedback_count": len(self.user_feedback),
            "data_quality_score": self._calculate_quality_score(),
            "recommendations": self._generate_recommendations()
        }

        # Count examples per intent
        for example in self.training_examples:
            intent = example.intent
            if intent not in report["examples_per_intent"]:
                report["examples_per_intent"][intent] = 0
            report["examples_per_intent"][intent] += 1

        return report

    def export_training_data(self, format: str = "json") -> str:
        """Export training data in specified format"""
        if format == "json":
            return json.dumps({
                "training_examples": [asdict(ex) for ex in self.training_examples],
                "intent_data": {k: asdict(v) for k, v in self.intent_data.items()},
                "user_feedback": self.user_feedback
            }, indent=2)
        else:
            raise ValueError(f"Unsupported format: {format}")

    def _load_training_examples(self) -> List[TrainingExample]:
        """Load training examples from file"""
        if self.examples_file.exists():
            try:
                with open(self.examples_file, 'r') as f:
                    data = json.load(f)
                return [TrainingExample(**ex) for ex in data]
            except Exception as e:
                logger.error(f"Failed to load training examples: {e}")
        return []

    def _load_intent_data(self) -> Dict[str, IntentTrainingData]:
        """Load intent training data from file"""
        if self.intents_file.exists():
            try:
                with open(self.intents_file, 'r') as f:
                    data = json.load(f)
                return {k: IntentTrainingData(**v) for k, v in data.items()}
            except Exception as e:
                logger.error(f"Failed to load intent data: {e}")
        return {}

    def _load_user_feedback(self) -> List[Dict[str, Any]]:
        """Load user feedback from file"""
        if self.feedback_file.exists():
            try:
                with open(self.feedback_file, 'r') as f:
                    return json.load(f)
            except Exception as e:
                logger.error(f"Failed to load user feedback: {e}")
        return []

    def _save_training_examples(self):
        """Save training examples to file"""
        try:
            with open(self.examples_file, 'w') as f:
                json.dump([asdict(ex) for ex in self.training_examples], f, indent=2)
        except Exception as e:
            logger.error(f"Failed to save training examples: {e}")

    def _save_intent_data(self):
        """Save intent data to file"""
        try:
            with open(self.intents_file, 'w') as f:
                json.dump({k: asdict(v) for k, v in self.intent_data.items()}, f, indent=2)
        except Exception as e:
            logger.error(f"Failed to save intent data: {e}")

    def _save_user_feedback(self):
        """Save user feedback to file"""
        try:
            with open(self.feedback_file, 'w') as f:
                json.dump(self.user_feedback, f, indent=2)
        except Exception as e:
            logger.error(f"Failed to save user feedback: {e}")

    def _calculate_quality_score(self) -> float:
        """Calculate overall data quality score"""
        if not self.training_examples:
            return 0.0

        # Factors to consider:
        # 1. Coverage of intents
        # 2. Number of examples per intent
        # 3. User feedback quality
        # 4. Pattern coverage

        intent_coverage = len(set(ex.intent for ex in self.training_examples)) / 20  # Assuming 20 total intents
        avg_examples = len(self.training_examples) / max(1, len(set(ex.intent for ex in self.training_examples)))
        feedback_quality = min(1.0, len(self.user_feedback) / 100)  # Normalize to 0-1

        score = (intent_coverage * 0.4 + 
                min(1.0, avg_examples / 10) * 0.4 + 
                feedback_quality * 0.2)

        return round(score, 2)

    def _generate_recommendations(self) -> List[str]:
        """Generate recommendations for improving training data"""
        recommendations = []

        # Check intent coverage
        covered_intents = set(ex.intent for ex in self.training_examples)
        all_intents = set(self.intent_data.keys())
        missing_intents = all_intents - covered_intents

        if missing_intents:
            recommendations.append(f"Add training examples for missing intents: {', '.join(missing_intents)}")

        # Check examples per intent
        intent_counts = {}
        for example in self.training_examples:
            intent_counts[example.intent] = intent_counts.get(example.intent, 0) + 1

        for intent, count in intent_counts.items():
            if count < 5:
                recommendations.append(f"Add more examples for '{intent}' (currently {count})")

        # Check feedback
        if len(self.user_feedback) < 10:
            recommendations.append("Collect more user feedback to improve accuracy")

        return recommendations

# Global training data manager instance
training_data_manager = TrainingDataManager()

def add_training_example(message: str, intent: str, confidence: float, 
                        entities: Dict[str, Any], context: Dict[str, Any]):
    """Convenience function to add training example"""
    example = TrainingExample(
        message=message,
        intent=intent,
        confidence=confidence,
        entities=entities,
        context=context,
        timestamp=datetime.now().timestamp()
    )
    training_data_manager.add_training_example(example)

def add_user_feedback(original_intent: str, corrected_intent: str, 
                     message: str, feedback: str):
    """Convenience function to add user feedback"""
    training_data_manager.add_user_feedback(original_intent, corrected_intent, message, feedback)

""" Observability System for Nova Agent
Provides comprehensive monitoring, metrics, and health checks: - Prometheus metrics collection - Health check endpoints - Centralized audit logging - Performance monitoring - Alert system """
import time import logging import json from datetime import datetime from typing import Dict, List, Any, Optional from pathlib import Path from collections import defaultdict, deque import threading
from prometheus_client import Counter, Histogram, Gauge, Summary, generate_latest import psutil
from utils.memory_manager import store_long
logger = logging.getLogger(__name__)
class NovaObservability: """ Comprehensive observability system for Nova Agent. """
def __init__(self, metrics_dir: str = "data/metrics"): self.metrics_dir = Path(metrics_dir) self.metrics_dir.mkdir(parents=True, exist_ok=True)
# Initialize Prometheus metrics self._init_prometheus_metrics()
# Performance tracking self.performance_history = deque(maxlen=1000) self.error_history = deque(maxlen=100) self.audit_log = deque(maxlen=10000)
# System monitoring self.start_time = time.time() self.last_health_check = time.time()
# Thread safety self._lock = threading.Lock()
def _init_prometheus_metrics(self): """Initialize Prometheus metrics.""" # Create a unique registry for this instance to avoid conflicts from prometheus_client import CollectorRegistry self.registry = CollectorRegistry()
# Request metrics self.request_counter = Counter( 'nova_requests_total', 'Total number of requests', ['method', 'endpoint', 'status'], registry=self.registry )
self.request_duration = Histogram( 'nova_request_duration_seconds', 'Request duration in seconds', ['method', 'endpoint'], registry=self.registry )
# NLP metrics self.nlp_requests = Counter( 'nova_nlp_requests_total', 'Total NLP requests', ['intent_type', 'confidence_level'], registry=self.registry )
self.nlp_accuracy = Gauge( 'nova_nlp_accuracy', 'NLP intent classification accuracy', registry=self.registry )
# Memory metrics self.memory_operations = Counter( 'nova_memory_operations_total', 'Memory operations', ['operation_type', 'namespace'], registry=self.registry )
self.memory_size = Gauge( 'nova_memory_size_bytes', 'Memory storage size in bytes', registry=self.registry )
# System metrics self.cpu_usage = Gauge( 'nova_cpu_usage_percent', 'CPU usage percentage', registry=self.registry )
self.memory_usage = Gauge( 'nova_memory_usage_bytes', 'Memory usage in bytes', registry=self.registry )
self.disk_usage = Gauge( 'nova_disk_usage_bytes', 'Disk usage in bytes', registry=self.registry )
# Research metrics self.research_experiments = Counter( 'nova_research_experiments_total', 'Research experiments', ['status', 'category'], registry=self.registry )
self.research_success_rate = Gauge( 'nova_research_success_rate', 'Research experiment success rate', registry=self.registry )
# Governance metrics self.governance_cycles = Counter( 'nova_governance_cycles_total', 'Governance cycles', ['status'], registry=self.registry )
self.governance_duration = Histogram( 'nova_governance_duration_seconds', 'Governance cycle duration in seconds', registry=self.registry )
# Error metrics self.error_counter = Counter( 'nova_errors_total', 'Total errors', ['error_type', 'module'], registry=self.registry )
# Performance summary self.performance_summary = Summary( 'nova_performance_summary', 'Performance summary statistics', registry=self.registry )
def record_request(self, method: str, endpoint: str, status: int, duration: float): """Record a request metric.""" self.request_counter.labels(method=method, endpoint=endpoint, status=status).inc() self.request_duration.labels(method=method, endpoint=endpoint).observe(duration)
# Store in audit log self._add_audit_entry({ "type": "request", "method": method, "endpoint": endpoint, "status": status, "duration": duration, "timestamp": datetime.now().isoformat() })
def record_nlp_request(self, intent_type: str, confidence: float): """Record an NLP request metric.""" confidence_level = self._get_confidence_level(confidence) self.nlp_requests.labels(intent_type=intent_type, confidence_level=confidence_level).inc()
# Update accuracy gauge self._update_nlp_accuracy()
def record_memory_operation(self, operation: str, namespace: str, size_bytes: int = 0): """Record a memory operation metric.""" self.memory_operations.labels(operation_type=operation, namespace=namespace).inc()
if size_bytes > 0: self.memory_size.inc(size_bytes)
def record_research_experiment(self, status: str, category: str, success: bool): """Record a research experiment metric.""" self.research_experiments.labels(status=status, category=category).inc()
# Update success rate self._update_research_success_rate()
def record_governance_cycle(self, status: str, duration: float): """Record a governance cycle metric.""" self.governance_cycles.labels(status=status).inc() self.governance_duration.observe(duration)
def record_error(self, error_type: str, module: str, error_message: str): """Record an error metric.""" self.error_counter.labels(error_type=error_type, module=module).inc()
# Store in error history with self._lock: self.error_history.append({ "type": error_type, "module": module, "message": error_message, "timestamp": datetime.now().isoformat() })
# Store in audit log self._add_audit_entry({ "type": "error", "error_type": error_type, "module": module, "message": error_message, "timestamp": datetime.now().isoformat() })
def update_system_metrics(self): """Update system metrics.""" try: # CPU usage cpu_percent = psutil.cpu_percent(interval=1) self.cpu_usage.set(cpu_percent)
# Memory usage memory = psutil.virtual_memory() self.memory_usage.set(memory.used)
# Disk usage disk = psutil.disk_usage('/') self.disk_usage.set(disk.used)
# Store performance data performance_data = { "timestamp": datetime.now().isoformat(), "cpu_percent": cpu_percent, "memory_used": memory.used, "memory_percent": memory.percent, "disk_used": disk.used, "disk_percent": (disk.used / disk.total) * 100 }
with self._lock: self.performance_history.append(performance_data)
except Exception as e: logger.error(f"Failed to update system metrics: {e}")
def get_health_status(self) -> Dict[str, Any]: """Get comprehensive health status.""" try: # System health system_health = self._check_system_health()
# Service health service_health = self._check_service_health()
# Memory health memory_health = self._check_memory_health()
# Overall health overall_health = "healthy" issues = []
if system_health["status"] != "healthy": overall_health = "degraded" issues.extend(system_health.get("issues", []))
if service_health["status"] != "healthy": overall_health = "degraded" issues.extend(service_health.get("issues", []))
if memory_health["status"] != "healthy": overall_health = "degraded" issues.extend(memory_health.get("issues", []))
if len(issues) > 5: overall_health = "unhealthy"
return { "status": overall_health, "timestamp": datetime.now().isoformat(), "uptime_seconds": time.time() - self.start_time, "system": system_health, "services": service_health, "memory": memory_health, "issues": issues, "last_health_check": self.last_health_check }
except Exception as e: logger.error(f"Health check failed: {e}") return { "status": "unhealthy", "error": str(e), "timestamp": datetime.now().isoformat() }
def _check_system_health(self) -> Dict[str, Any]: """Check system health.""" try: cpu_percent = psutil.cpu_percent(interval=1) memory = psutil.virtual_memory() disk = psutil.disk_usage('/')
issues = [] status = "healthy"
if cpu_percent > 80: issues.append(f"High CPU usage: {cpu_percent}%") status = "degraded"
if memory.percent > 85: issues.append(f"High memory usage: {memory.percent}%") status = "degraded"
disk_percent = (disk.used / disk.total) * 100 if disk_percent > 90: issues.append(f"High disk usage: {disk_percent:.1f}%") status = "degraded"
return { "status": status, "cpu_percent": cpu_percent, "memory_percent": memory.percent, "disk_percent": disk_percent, "issues": issues }
except Exception as e: return { "status": "unhealthy", "error": str(e), "issues": [f"System check failed: {str(e)}"] }
def _check_service_health(self) -> Dict[str, Any]: """Check service health.""" try: issues = [] status = "healthy"
# Check if recent errors are too frequent recent_errors = [e for e in self.error_history if (datetime.now() - datetime.fromisoformat(e["timestamp"])).seconds < 300]
if len(recent_errors) > 10: issues.append(f"Too many recent errors: {len(recent_errors)} in last 5 minutes") status = "degraded"
# Check if requests are failing # This would need to be implemented based on actual request tracking
return { "status": status, "recent_errors": len(recent_errors), "issues": issues }
except Exception as e: return { "status": "unhealthy", "error": str(e), "issues": [f"Service check failed: {str(e)}"] }
def _check_memory_health(self) -> Dict[str, Any]: """Check memory system health.""" try: from utils.memory_manager import get_global_memory_manager mm = get_global_memory_manager() memory_status = mm.get_memory_status()
issues = [] status = "healthy"
if not memory_status["fully_available"]: issues.append("Memory system not fully available") status = "degraded"
if not memory_status["weaviate_available"]: issues.append("Weaviate not available") status = "degraded"
if not memory_status["sentence_transformers_available"]: issues.append("Sentence transformers not available") status = "degraded"
return { "status": status, "memory_status": memory_status, "issues": issues }
except Exception as e: return { "status": "unhealthy", "error": str(e), "issues": [f"Memory check failed: {str(e)}"] }
def get_metrics(self) -> str: """Get Prometheus metrics.""" return generate_latest(self.registry)
def get_performance_summary(self) -> Dict[str, Any]: """Get performance summary.""" try: with self._lock: if not self.performance_history: return {"error": "No performance data available"}
recent_data = list(self.performance_history)[-100:] # Last 100 entries
cpu_values = [d["cpu_percent"] for d in recent_data] memory_values = [d["memory_percent"] for d in recent_data] disk_values = [d["disk_percent"] for d in recent_data]
return { "summary": { "cpu": { "current": cpu_values[-1] if cpu_values else 0, "average": sum(cpu_values) / len(cpu_values) if cpu_values else 0, "max": max(cpu_values) if cpu_values else 0, "min": min(cpu_values) if cpu_values else 0 }, "memory": { "current": memory_values[-1] if memory_values else 0, "average": sum(memory_values) / len(memory_values) if memory_values else 0, "max": max(memory_values) if memory_values else 0, "min": min(memory_values) if memory_values else 0 }, "disk": { "current": disk_values[-1] if disk_values else 0, "average": sum(disk_values) / len(disk_values) if disk_values else 0, "max": max(disk_values) if disk_values else 0, "min": min(disk_values) if disk_values else 0 } }, "data_points": len(recent_data), "time_range": "Last 100 measurements" }
except Exception as e: logger.error(f"Failed to get performance summary: {e}") return {"error": str(e)}
def get_audit_log(self, limit: int = 100, log_type: Optional[str] = None) -> List[Dict[str, Any]]: """Get audit log entries.""" try: with self._lock: if log_type: filtered_log = [entry for entry in self.audit_log if entry.get("type") == log_type] return list(filtered_log)[-limit:] else: return list(self.audit_log)[-limit:]
except Exception as e: logger.error(f"Failed to get audit log: {e}") return []
def get_error_summary(self) -> Dict[str, Any]: """Get error summary.""" try: with self._lock: if not self.error_history: return {"error": "No error data available"}
# Group errors by type error_counts = defaultdict(int) module_counts = defaultdict(int)
for error in self.error_history: error_counts[error["type"]] += 1 module_counts[error["module"]] += 1
recent_errors = [e for e in self.error_history if (datetime.now() - datetime.fromisoformat(e["timestamp"])).seconds < 3600]
return { "total_errors": len(self.error_history), "recent_errors": len(recent_errors), "error_types": dict(error_counts), "error_modules": dict(module_counts), "latest_errors": list(self.error_history)[-10:] # Last 10 errors }
except Exception as e: logger.error(f"Failed to get error summary: {e}") return {"error": str(e)}
def _add_audit_entry(self, entry: Dict[str, Any]): """Add an entry to the audit log.""" with self._lock: self.audit_log.append(entry)
# Store in long-term memory try: store_long("audit", "log", json.dumps(entry)) except Exception as e: logger.error(f"Failed to store audit entry: {e}")
def _get_confidence_level(self, confidence: float) -> str: """Convert confidence score to level.""" if confidence >= 0.9: return "very_high" elif confidence >= 0.8: return "high" elif confidence >= 0.7: return "medium" elif confidence >= 0.6: return "low" else: return "very_low"
def _update_nlp_accuracy(self): """Update NLP accuracy gauge.""" try: # This would need to be implemented based on actual accuracy tracking # For now, use a placeholder value self.nlp_accuracy.set(0.85) except Exception as e: logger.error(f"Failed to update NLP accuracy: {e}")
def _update_research_success_rate(self): """Update research success rate gauge.""" try: # This would need to be implemented based on actual success tracking # For now, use a placeholder value self.research_success_rate.set(0.75) except Exception as e: logger.error(f"Failed to update research success rate: {e}")
def start_monitoring(self): """Start the monitoring loop.""" def monitor_loop(): while True: try: self.update_system_metrics() self.last_health_check = time.time() time.sleep(60) # Update every minute except Exception as e: logger.error(f"Monitoring loop error: {e}") time.sleep(60)
monitor_thread = threading.Thread(target=monitor_loop, daemon=True) monitor_thread.start() logger.info("Observability monitoring started")
# Global observability instance nova_observability = NovaObservability()
def get_health_status(): """Get health status.""" return nova_observability.get_health_status()
def get_metrics(): """Get Prometheus metrics.""" return nova_observability.get_metrics()
def get_performance_summary(): """Get performance summary.""" return nova_observability.get_performance_summary()
def get_audit_log(limit: int = 100, log_type: Optional[str] = None): """Get audit log.""" return nova_observability.get_audit_log(limit, log_type)
def get_error_summary(): """Get error summary.""" return nova_observability.get_error_summary()
def record_request(method: str, endpoint: str, status: int, duration: float): """Record a request.""" nova_observability.record_request(method, endpoint, status, duration)
def record_error(error_type: str, module: str, error_message: str): """Record an error.""" nova_observability.record_error(error_type, module, error_message)

""" Advanced Analysis Phase for Nova Agent
This module provides sophisticated message analysis using: - Advanced NLP intent classification - Context-aware processing - Entity extraction - Confidence scoring """
import logging from typing import Dict, Any from nova.nlp import classify_intent, get_context_for_intent, update_system_state from nova.nlp.intent_classifier import IntentType import time
logger = logging.getLogger(__name__)
def analyze(message: str) -> Dict[str, Any]: """ Advanced message analysis using NLP intent classification
Args: message: User input message to analyze
Returns: Dictionary containing analysis results with intent, confidence, entities, and context """ try: # Get context for better intent classification context = get_context_for_intent(message)
# Classify intent using advanced NLP intent_result = classify_intent(message, context)
# Log the classification for debugging logger.info(f"Intent classified: {intent_result.intent.value} " f"(confidence: {intent_result.confidence:.2f}, " f"method: {intent_result.classification_method})")
# Prepare analysis result analysis = { "intent": intent_result.intent.value, "confidence": intent_result.confidence, "entities": intent_result.entities, "context": context, "raw_message": message, "classification_method": intent_result.classification_method, "timestamp": intent_result.context.get("timestamp", 0) }
# Add intent-specific metadata analysis.update(_get_intent_metadata(intent_result))
# Update system state based on intent _update_system_state_from_intent(intent_result)
return analysis
except Exception as e: logger.error(f"Analysis failed: {e}") # Fallback to basic analysis return { "intent": "unknown", "confidence": 0.0, "entities": {}, "context": {}, "raw_message": message, "classification_method": "fallback", "error": str(e) }
def _get_intent_metadata(intent_result) -> Dict[str, Any]: """Get additional metadata based on the classified intent""" metadata = {}
if intent_result.intent == IntentType.GET_RPM: metadata["requires_real_time_data"] = True metadata["data_sources"] = ["analytics", "platform_apis"]
elif intent_result.intent == IntentType.CREATE_CONTENT: metadata["requires_ai_generation"] = True metadata["estimated_processing_time"] = "30-60 seconds"
elif intent_result.intent == IntentType.SWITCH_AVATAR: metadata["requires_avatar_validation"] = True metadata["available_avatars"] = ["Avatar 1", "Avatar 2", "Avatar 3"]
elif intent_result.intent == IntentType.RESUME_LOOP: metadata["requires_system_check"] = True metadata["estimated_startup_time"] = "10-30 seconds"
elif intent_result.intent == IntentType.QUERY_MEMORY: metadata["requires_memory_search"] = True metadata["search_depth"] = "recent_50_turns"
return metadata
def _update_system_state_from_intent(intent_result): """Update system state based on the classified intent""" try: if intent_result.intent == IntentType.RESUME_LOOP: update_system_state(loop_active=True, current_task="system_startup")
elif intent_result.intent == IntentType.PAUSE_LOOP: update_system_state(loop_active=False, current_task=None)
elif intent_result.intent == IntentType.GET_RPM: update_system_state(last_rpm_check=time.time())
elif intent_result.intent == IntentType.CREATE_CONTENT: update_system_state(last_content_created=time.time())
elif intent_result.intent == IntentType.SWITCH_AVATAR: # Extract avatar from entities if available new_avatar = intent_result.entities.get("avatar", "default") update_system_state(current_avatar=new_avatar)
except Exception as e: logger.error(f"Failed to update system state: {e}")
# Legacy compatibility function def analyze_legacy(message: str) -> Dict[str, Any]: """ Legacy analysis function for backward compatibility
This maintains the old simple string matching approach """ if message.lower().startswith("resume"): return {"intent": "resume"} if "rpm" in message.lower(): return {"intent": "rpm"} return {"intent": "generic", "msg": message}

"""
Advanced Execution Phase for Nova Agent

This module provides sophisticated action execution based on:
- Advanced planning results
- Parameter validation
- Execution strategies
- Error handling and recovery
"""

import logging
from typing import Dict, Any
import time

logger = logging.getLogger(__name__)

def execute(plan: Dict[str, Any]) -> str:
    """
    Advanced action execution based on planning results

    Args:
        plan: Result from plan_phase containing action, parameters, strategy, etc.

    Returns:
        String response describing the execution result
    """
    try:
        action = plan.get("action", "unknown")
        parameters = plan.get("parameters", {})
        execution_strategy = plan.get("execution_strategy", {})
        confidence = plan.get("confidence", 0.0)

        logger.info(f"Executing action: {action} (confidence: {confidence:.2f})")

        # Handle different action types
        if action == "resume_loop":
            return _execute_resume_loop(parameters, execution_strategy)
        elif action == "pause_loop":
            return _execute_pause_loop(parameters, execution_strategy)
        elif action == "get_rpm":
            return _execute_get_rpm(parameters, execution_strategy)
        elif action == "get_analytics":
            return _execute_get_analytics(parameters, execution_strategy)
        elif action == "create_content":
            return _execute_create_content(parameters, execution_strategy)
        elif action == "switch_avatar":
            return _execute_switch_avatar(parameters, execution_strategy)
        elif action == "query_memory":
            return _execute_query_memory(parameters, execution_strategy)
        elif action == "help":
            return _execute_help(parameters, execution_strategy)
        elif action == "confirm_intent":
            return _execute_confirm_intent(plan)
        elif action == "clarify_intent":
            return _execute_clarify_intent(plan)
        elif action == "status_check":
            return _execute_status_check(parameters, execution_strategy)
        elif action == "error_handling":
            return _execute_error_handling(plan)
        else:
            return _execute_chat(plan)

    except Exception as e:
        logger.error(f"Execution failed: {e}")
        return f"❌ Execution error: {str(e)}"

def _execute_resume_loop(parameters: Dict[str, Any], strategy: Dict[str, Any]) -> str:
    """Execute resume loop action"""
    try:
        # Validate system health if required
        if parameters.get("check_system_health", False):
            health_status = _check_system_health()
            if not health_status["healthy"]:
                return f"⚠️ System health check failed: {health_status['issues']}"

        # Validate credentials if required
        if parameters.get("validate_credentials", False):
            cred_status = _validate_credentials()
            if not cred_status["valid"]:
                return f"⚠️ Credential validation failed: {cred_status['issues']}"

        # Start monitoring if required
        if parameters.get("start_monitoring", False):
            _start_monitoring()

        # Update system state
        from nova.nlp import update_system_state
        update_system_state(loop_active=True, current_task="nova_automation")

        return "🔄 Nova automation loop resumed successfully. System is now active and monitoring."

    except Exception as e:
        logger.error(f"Resume loop execution failed: {e}")
        return f"❌ Failed to resume loop: {str(e)}"

def _execute_pause_loop(parameters: Dict[str, Any], strategy: Dict[str, Any]) -> str:
    """Execute pause loop action"""
    try:
        # Graceful shutdown if required
        if parameters.get("graceful_shutdown", False):
            _perform_graceful_shutdown()

        # Save state if required
        if parameters.get("save_state", False):
            _save_system_state()

        # Notify user if required
        if parameters.get("notify_user", False):
            _notify_user("Nova loop paused")

        # Update system state
        from nova.nlp import update_system_state
        update_system_state(loop_active=False, current_task=None)

        return "⏸️ Nova automation loop paused successfully. System is now inactive."

    except Exception as e:
        logger.error(f"Pause loop execution failed: {e}")
        return f"❌ Failed to pause loop: {str(e)}"

