        print(low_rpm[["avatar", "hook", "rpm"]])
    else:
        print("✅ No major RPM issues detected")

#!/usr/bin/env python3 """ Nova Agent Security Validation Script
This script performs comprehensive security checks before deployment: 1. Environment variable validation 2. Configuration file security audit 3. Dependency vulnerability scan 4. Secret detection in codebase
Usage: python scripts/security_check.py python scripts/security_check.py --fix-deps # Attempt to upgrade vulnerable dependencies """
import sys import subprocess import json from pathlib import Path
# Add project root to Python path PROJECT_ROOT = Path(__file__).parent.parent sys.path.insert(0, str(PROJECT_ROOT))
try: from nova.config.env import validate_env_or_exit, FORBIDDEN except ImportError as e: print(f"❌ Failed to import Nova modules: {e}") print("Make sure you're running this from the project root directory.") sys.exit(1)
class SecurityChecker: def __init__(self): self.issues = [] self.warnings = []
def add_issue(self, severity: str, category: str, message: str, fix: str = None): """Add a security issue.""" self.issues.append({ 'severity': severity, 'category': category, 'message': message, 'fix': fix })
def add_warning(self, message: str): """Add a warning.""" self.warnings.append(message)
def check_environment_variables(self) -> bool: """Check that all required environment variables are set securely.""" print("🔍 Checking environment configuration...")
try: validate_env_or_exit() print("✅ Environment validation passed") return True except SystemExit: self.add_issue( 'CRITICAL', 'Environment', 'Required environment variables are missing or insecure', 'Set all required environment variables from config/env.production.template' ) return False
def check_config_files(self) -> bool: """Check configuration files for hardcoded secrets.""" print("🔍 Checking configuration files for hardcoded secrets...")
config_files = [ 'config/production_config.yaml', 'config/settings.yaml', 'governance_config.yaml' ]
issues_found = False
for config_file in config_files: config_path = PROJECT_ROOT / config_file if not config_path.exists(): continue
try: with open(config_path, 'r') as f: content = f.read()
# Check for forbidden values for forbidden in FORBIDDEN: if forbidden in content.lower(): self.add_issue( 'HIGH', 'Configuration', f'Potentially insecure value "{forbidden}" found in {config_file}', f'Replace hardcoded values with environment variables in {config_file}' ) issues_found = True
# Check for email/password patterns if 'password' in content.lower() and '${' not in content: lines_with_password = [line.strip() for line in content.split('\n') if 'password' in line.lower() and not line.strip().startswith('#')] if lines_with_password: self.add_warning(f"Password-related configuration in {config_file}: {lines_with_password}")
except Exception as e: self.add_warning(f"Could not check {config_file}: {e}")
if not issues_found: print("✅ No hardcoded secrets found in configuration files")
return not issues_found
def check_dependencies(self, fix_deps: bool = False) -> bool: """Check for vulnerable dependencies.""" print("🔍 Checking dependencies for security vulnerabilities...")
try: # Try to run pip-audit result = subprocess.run([ sys.executable, '-m', 'pip_audit', '--requirement', str(PROJECT_ROOT / 'requirements.txt'), '--format', 'json' ], capture_output=True, text=True, cwd=PROJECT_ROOT)
if result.returncode == 0: try: audit_data = json.loads(result.stdout) vulnerabilities = audit_data.get('vulnerabilities', [])
if vulnerabilities: self.add_issue( 'HIGH', 'Dependencies', f'Found {len(vulnerabilities)} security vulnerabilities in dependencies', 'Run: pip-audit --requirement requirements.txt --fix' if fix_deps else 'Upgrade vulnerable packages' )
# Show top 3 vulnerabilities for vuln in vulnerabilities[:3]: package = vuln.get('package', 'unknown') id = vuln.get('id', 'unknown') print(f" - {package}: {id}")
if fix_deps: print("🔧 Attempting to fix dependencies...") fix_result = subprocess.run([ sys.executable, '-m', 'pip_audit', '--requirement', str(PROJECT_ROOT / 'requirements.txt'), '--fix' ], cwd=PROJECT_ROOT)
if fix_result.returncode == 0: print("✅ Dependencies fixed successfully") return True else: print("❌ Failed to fix all dependencies automatically")
return False else: print("✅ No known vulnerabilities in dependencies") return True
except json.JSONDecodeError: self.add_warning("Could not parse pip-audit output") return True # Don't fail if we can't parse the output
except FileNotFoundError: self.add_warning("pip-audit not available - install with: pip install pip-audit") return True # Don't fail if pip-audit isn't installed except Exception as e: self.add_warning(f"Dependency check failed: {e}") return True # Don't fail the entire check for dependency scan issues
return True # Default to True if we reach here
def check_secrets_in_code(self) -> bool: """Check for accidentally committed secrets in code.""" print("🔍 Scanning code for potential secrets...")
# Patterns that might indicate secrets
issues_found = False
# Scan Python files for py_file in PROJECT_ROOT.rglob('*.py'): if '.venv' in str(py_file) or '__pycache__' in str(py_file): continue
try: with open(py_file, 'r', encoding='utf-8') as f: content = f.read()
# Check for forbidden hardcoded values for forbidden in FORBIDDEN: if f'"{forbidden}"' in content or f"'{forbidden}'" in content: self.add_issue( 'MEDIUM', 'Code Security', f'Potentially hardcoded insecure value "{forbidden}" in {py_file}', f'Replace with environment variable in {py_file}' ) issues_found = True
except Exception as e: self.add_warning(f"Could not scan {py_file}: {e}")
if not issues_found: print("✅ No obvious secrets found in code")
return not issues_found
def run_comprehensive_check(self, fix_deps: bool = False) -> bool: """Run all security checks.""" print("🛡️ Running Nova Agent Security Check\n")
all_passed = True
# Run all checks all_passed &= self.check_environment_variables() all_passed &= self.check_config_files() all_passed &= self.check_dependencies(fix_deps) all_passed &= self.check_secrets_in_code()
# Report results print("\n📊 Security Check Results:") print("=" * 50)
if self.issues: print(f"❌ Found {len(self.issues)} security issues:") for issue in self.issues: print(f" [{issue['severity']}] {issue['category']}: {issue['message']}") if issue['fix']: print(f" 💡 Fix: {issue['fix']}")
if self.warnings: print(f"\n⚠️ {len(self.warnings)} warnings:") for warning in self.warnings: print(f" - {warning}")
print(f"\n🎯 Overall Status: {'✅ SECURE' if all_passed else '❌ ISSUES FOUND'}")
if not all_passed: print("\n🚨 Fix all security issues before deploying to production!")
return all_passed
def main(): """Main function.""" import argparse
parser = argparse.ArgumentParser(description='Nova Agent Security Validator') parser.add_argument('--fix-deps', action='store_true', help='Attempt to automatically fix dependency vulnerabilities')
args = parser.parse_args()
checker = SecurityChecker() success = checker.run_comprehensive_check(fix_deps=args.fix_deps)
sys.exit(0 if success else 1)
if __name__ == '__main__': main()

"""
Secret Management and Rotation for Nova Agent

This module provides advanced secret management capabilities including
automatic rotation, secure storage, and audit logging.
"""

import os
import json
import logging
import hashlib
from datetime import datetime
from typing import Dict, List, Optional, Any
from dataclasses import dataclass
from pathlib import Path


@dataclass
class SecretMetadata:
    """Metadata for a secret including rotation and audit info."""
    name: str
    created_at: datetime
    last_rotated: datetime
    expires_at: Optional[datetime]
    hash: str
    source: str  # 'env', 'vault', 'file'
    rotation_policy: str  # 'manual', 'auto', 'never'


class SecretManager:
    """Advanced secret management with rotation and audit capabilities."""

    def __init__(self, audit_log_path: str = "logs/secret_audit.json"):
        self.audit_log_path = Path(audit_log_path)
        self.audit_log_path.parent.mkdir(exist_ok=True)
        self.logger = logging.getLogger(__name__)

        # Rotation policies (in days)
        self.rotation_policies = {
            "JWT_SECRET_KEY": 90,  # Rotate JWT secrets every 90 days
            "OPENAI_API_KEY": 365,  # API keys typically last longer
            "WEAVIATE_API_KEY": 180,
            "EMAIL_PASSWORD": 90,
        }

        # Load existing audit log
        self.audit_log = self._load_audit_log()

    def get_secret(self, name: str, required: bool = True) -> Optional[str]:
        """Get a secret with rotation checking and audit logging."""
        value = os.getenv(name)

        if not value and required:
            raise RuntimeError(f"Missing required secret: {name}")

        if value:
            self._audit_secret_access(name, value)
            self._check_rotation_needed(name, value)

        return value

    def _audit_secret_access(self, name: str, value: str):
        """Audit secret access for security monitoring."""
        access_record = {
            "timestamp": datetime.utcnow().isoformat(),
            "secret_name": name,
            "action": "access",
            "hash": self._hash_secret(value),
            "source": "environment"
        }

        self.audit_log.append(access_record)
        self._save_audit_log()

        self.logger.info(f"Secret accessed: {name}")

    def _check_rotation_needed(self, name: str, value: str):
        """Check if a secret needs rotation based on policy."""
        if name not in self.rotation_policies:
            return

        # Get last rotation info
        last_rotation = self._get_last_rotation(name)
        if not last_rotation:
            self._record_rotation(name, value)
            return

        days_since_rotation = (datetime.utcnow() - last_rotation).days
        max_age = self.rotation_policies[name]

        if days_since_rotation > max_age:
            self.logger.warning(
                f"Secret {name} is {days_since_rotation} days old "
                f"(max: {max_age} days). Consider rotation."
            )

    def _get_last_rotation(self, name: str) -> Optional[datetime]:
        """Get the last rotation time for a secret."""
        for record in reversed(self.audit_log):
            if (record.get("secret_name") == name and 
                record.get("action") == "rotation"):
                return datetime.fromisoformat(record["timestamp"])
        return None

    def _record_rotation(self, name: str, value: str):
        """Record a secret rotation."""
        rotation_record = {
            "timestamp": datetime.utcnow().isoformat(),
            "secret_name": name,
            "action": "rotation",
            "hash": self._hash_secret(value),
            "source": "environment"
        }

        self.audit_log.append(rotation_record)
        self._save_audit_log()

        self.logger.info(f"Secret rotation recorded: {name}")

    def _hash_secret(self, value: str) -> str:
        """Create a hash of a secret for audit purposes."""
        return hashlib.sha256(value.encode()).hexdigest()[:16]

    def _load_audit_log(self) -> List[Dict[str, Any]]:
        """Load the audit log from file."""
        if not self.audit_log_path.exists():
            return []

        try:
            with open(self.audit_log_path, 'r') as f:
                return json.load(f)
        except Exception as e:
            self.logger.error(f"Failed to load audit log: {e}")
            return []

    def _save_audit_log(self):
        """Save the audit log to file."""
        try:
            with open(self.audit_log_path, 'w') as f:
                json.dump(self.audit_log, f, indent=2)
        except Exception as e:
            self.logger.error(f"Failed to save audit log: {e}")

    def get_secret_health_report(self) -> Dict[str, Any]:
        """Generate a health report for all secrets."""
        report = {
            "timestamp": datetime.utcnow().isoformat(),
            "secrets": {},
            "warnings": [],
            "critical_issues": []
        }

        for name, max_age in self.rotation_policies.items():
            value = os.getenv(name)
            if not value:
                report["critical_issues"].append(f"Missing required secret: {name}")
                continue

            last_rotation = self._get_last_rotation(name)
            if not last_rotation:
                report["secrets"][name] = {
                    "status": "unknown_age",
                    "last_rotation": None,
                    "days_since_rotation": None
                }
                continue

            days_since_rotation = (datetime.utcnow() - last_rotation).days
            status = "healthy"

            if days_since_rotation > max_age:
                status = "needs_rotation"
                report["warnings"].append(
                    f"Secret {name} is {days_since_rotation} days old "
                    f"(max: {max_age} days)"
                )
            elif days_since_rotation > max_age * 0.8:
                status = "approaching_rotation"
                report["warnings"].append(
                    f"Secret {name} will need rotation in "
                    f"{max_age - days_since_rotation} days"
                )

            report["secrets"][name] = {
                "status": status,
                "last_rotation": last_rotation.isoformat(),
                "days_since_rotation": days_since_rotation,
                "max_age_days": max_age
            }

        return report

    def validate_all_secrets(self) -> bool:
        """Validate all secrets are present and healthy."""
        health_report = self.get_secret_health_report()

        if health_report["critical_issues"]:
            for issue in health_report["critical_issues"]:
                self.logger.error(issue)
            return False

        if health_report["warnings"]:
            for warning in health_report["warnings"]:
                self.logger.warning(warning)

        return True


# Global secret manager instance
secret_manager = SecretManager()


def get_secure_secret(name: str, required: bool = True) -> Optional[str]:
    """Get a secret with enhanced security and audit logging."""
    return secret_manager.get_secret(name, required)


def validate_secrets() -> bool:
    """Validate all secrets are present and healthy."""
    return secret_manager.validate_all_secrets()


def get_secret_health() -> Dict[str, Any]:
    """Get a health report for all secrets."""
    return secret_manager.get_secret_health_report()

"""
Enhanced Security Validation for Nova Agent

This module provides comprehensive security validation for environment variables,
ensuring they meet security requirements and best practices.
"""

import os
import re
import secrets
from typing import List, Optional, Tuple
from dataclasses import dataclass


@dataclass
class SecurityValidationResult:
    """Result of security validation check."""
    is_valid: bool
    errors: List[str]
    warnings: List[str]


class SecurityValidator:
    """Enhanced security validator for environment variables."""

    def __init__(self):
        self.validation_rules = {
            "OPENAI_API_KEY": {
                "required": True,
                "pattern": r"^sk-[a-zA-Z0-9]{32,}$",
                "description": "OpenAI API key starting with 'sk-'",
                "min_length": 35
            },
            "JWT_SECRET_KEY": {
                "required": True,
                "pattern": r"^[a-zA-Z0-9!@#$%^&*()_+\-=\[\]{};':\"\\|,.<>\/?]{32,}$",
                "description": "Strong JWT secret (32+ chars, no spaces)",
                "min_length": 32,
                "forbidden_values": ["change-me", "default", "secret", "key"]
            },
            "WEAVIATE_API_KEY": {
                "required": True,
                "pattern": r"^[a-zA-Z0-9\-_]{20,}$",
                "description": "Weaviate API key (20+ chars)",
                "min_length": 20
            },
            "EMAIL_PASSWORD": {
                "required": True,
                "pattern": r"^[a-zA-Z0-9!@#$%^&*()_+\-=\[\]{};':\"\\|,.<>\/?]{16,}$",
                "description": "Email app password (16+ chars)",
                "min_length": 16,
                "forbidden_values": ["your_app_password_here", "password", "123456"]
            }
        }

    def validate_environment(self) -> SecurityValidationResult:
        """Validate all environment variables for security compliance."""
        errors = []
        warnings = []

        for var_name, rules in self.validation_rules.items():
            value = os.getenv(var_name)

            # Check if required
            if rules.get("required", False) and not value:
                errors.append(f"Missing required environment variable: {var_name}")
                continue

            if not value:
                continue  # Skip validation for optional variables

            # Check minimum length
            if "min_length" in rules and len(value) < rules["min_length"]:
                errors.append(f"{var_name}: Value too short (min {rules['min_length']} chars)")

            # Check pattern
            if "pattern" in rules and not re.match(rules["pattern"], value):
                errors.append(f"{var_name}: Invalid format - {rules['description']}")

            # Check forbidden values
            if "forbidden_values" in rules and value in rules["forbidden_values"]:
                errors.append(f"{var_name}: Using forbidden value '{value}'")

            # Security warnings
            if self._is_weak_secret(value):
                warnings.append(f"{var_name}: Consider using a stronger secret")

        # Additional security checks
        self._check_common_vulnerabilities(errors, warnings)

        return SecurityValidationResult(
            is_valid=len(errors) == 0,
            errors=errors,
            warnings=warnings
        )

    def _is_weak_secret(self, value: str) -> bool:
        """Check if a secret is potentially weak."""
        if len(value) < 16:
            return True

        # Check for common weak patterns
        weak_patterns = [
            r"^[a-z]+$",  # All lowercase
            r"^[A-Z]+$",  # All uppercase
            r"^[0-9]+$",  # All numbers
            r"^(.)\1+$",  # Repeated characters
        ]

        for pattern in weak_patterns:
            if re.match(pattern, value):
                return True

        return False

    def _check_common_vulnerabilities(self, errors: List[str], warnings: List[str]):
        """Check for common security vulnerabilities."""
        # Check for development secrets in production
        if os.getenv("NODE_ENV") == "production" or os.getenv("ENVIRONMENT") == "production":
            dev_secrets = ["test", "dev", "development", "localhost"]
            for var_name, value in os.environ.items():
                if any(secret in value.lower() for secret in dev_secrets):
                    warnings.append(f"{var_name}: Contains development-like value in production")

        # Check for exposed secrets in logs
        if os.getenv("LOG_LEVEL", "").upper() == "DEBUG":
            warnings.append("DEBUG logging enabled - ensure secrets are not logged")

    def generate_secure_secret(self, length: int = 64) -> str:
        """Generate a cryptographically secure secret."""
        return secrets.token_urlsafe(length)

    def validate_jwt_secret_strength(self, secret: str) -> Tuple[bool, List[str]]:
        """Validate JWT secret strength specifically."""
        issues = []

        if len(secret) < 32:
            issues.append("JWT secret should be at least 32 characters long")

        if not re.search(r"[A-Z]", secret):
            issues.append("JWT secret should contain uppercase letters")

        if not re.search(r"[a-z]", secret):
            issues.append("JWT secret should contain lowercase letters")

        if not re.search(r"[0-9]", secret):
            issues.append("JWT secret should contain numbers")

        if not re.search(r"[!@#$%^&*()_+\-=\[\]{};':\"\\|,.<>\/?]", secret):
            issues.append("JWT secret should contain special characters")

        return len(issues) == 0, issues


def get_required_env(var_name: str, validator: Optional[SecurityValidator] = None) -> str:
    """Fetch an environment variable with enhanced validation."""
    val = os.getenv(var_name)
    if not val:
        raise RuntimeError(f"Missing required environment variable: {var_name}")

    if validator:
        result = validator.validate_environment()
        if not result.is_valid:
            raise RuntimeError(f"Security validation failed for {var_name}: {'; '.join(result.errors)}")

    return val


def launch_setup() -> None:
    """Enhanced launch setup with security validation."""
    validator = SecurityValidator()

    # Validate all environment variables
    result = validator.validate_environment()

    if not result.is_valid:
        print("❌ Security validation failed:")
        for error in result.errors:
            print(f"   - {error}")
        raise RuntimeError("Environment validation failed")

    if result.warnings:
        print("⚠️  Security warnings:")
        for warning in result.warnings:
            print(f"   - {warning}")

    # Verify critical secrets
    required_vars = [
        "OPENAI_API_KEY",
        "WEAVIATE_URL", 
        "WEAVIATE_API_KEY",
        "JWT_SECRET_KEY"
    ]

    for var in required_vars:
        get_required_env(var, validator)

    print("✅ All required secrets validated. Launching Nova Agent...")

